function localizeTechnicalIdentifier(language: Language, identifier: string, prefix: string) {
  const words = identifier.replace(prefix, '').split('_')
  return language === 'vi' ? words.map((word) => technicalTerms[word] ?? word).filter(Boolean).join(' ') : words.join(' ')
}

export function localizePassiveSkill(language: Language, skillId: string) {
  return localizeTechnicalIdentifier(language, skillId, 'PASSIVE_')
}

export function localizeDoctrineAbility(language: Language, abilityId: string) {
  return localizeTechnicalIdentifier(language, abilityId, '')
}

export function localizeRareTrait(language: Language, traitId: string) {
  return localizeTechnicalIdentifier(language, traitId, '')
}

