export function localizeLog(language: Language, line: string) {
  line = line.replaceAll("\\'", "'")
  let match = line.match(/^(.+) used (ACTIVE_[A-Z0-9_]+)\.$/)
  if (match) return language === 'vi'
    ? `${localizeName(language, match[1])} sử dụng ${activeSkillNames.vi[match[2]] ?? activeSkillLabel(match[2])}.`
    : `${match[1]} used ${activeSkillNames.en[match[2]] ?? activeSkillLabel(match[2])}.`
  if (language === 'en') return line
  const staticLogs: Record<string, string> = {
    'The machine lights up, and the molten core reveals a passage into an eerie world teeming with alien flora. The expedition steps through the portal and finds itself surrounded by towering mushrooms, as tall as trees.': 'Cỗ máy bừng sáng, và lõi nóng chảy mở ra một lối đi tới thế giới kỳ dị tràn ngập hệ thực vật ngoài hành tinh. Đoàn thám hiểm bước qua cánh cổng và thấy mình bị bao quanh bởi những cây nấm cao vút như đại thụ.',
    '"You have to leave, or we\'ll feast on your bones"': '“Các ngươi phải rời đi, nếu không bọn ta sẽ gặm xương các ngươi.”',
    '"This was your last chance"': '“Đó là cơ hội cuối cùng của các ngươi.”',
    '"You will not wake it. Leave now, and don\'t interfere!"': '“Các ngươi sẽ không đánh thức nó. Rời đi ngay và đừng can thiệp!”',
    '"We won\'t allow you to hurt the Singularity!"': '“Bọn ta sẽ không cho phép các ngươi làm hại Điểm Kỳ Dị!”',
    'The frequency of the sound intensifies. It is now almost unbearable.': 'Tần số âm thanh tăng cao. Giờ nó gần như không thể chịu nổi.',
    'As they explore, strange patterns, resembling living animals, begin to flicker in rhythmic pulses.': 'Trong lúc khám phá, những hoa văn kỳ lạ giống các sinh vật sống bắt đầu chớp sáng theo nhịp.',
    'A deep rumbling echoes through the air. With each swell of sound, the visions grow more vivid.': 'Một tiếng ầm trầm sâu vang vọng trong không khí. Mỗi khi âm thanh dâng lên, những ảo ảnh càng trở nên sống động.',
    'Drawn to the source of the sound, the expedition pushes forward.': 'Bị nguồn âm thanh cuốn hút, đoàn thám hiểm tiếp tục tiến lên.',
    'The images of three horses materialize before the adventurers.': 'Hình ảnh ba con ngựa hiện hình trước các mạo hiểm giả.',
    '"You have to help them. Their suffering is immeasurable"': '“Các ngươi phải giúp họ. Nỗi đau của họ không thể đong đếm.”',
    'Baffled, the adventurers continue toward the sound.': 'Bối rối, các mạo hiểm giả tiếp tục đi về phía âm thanh.',
    'A different image materializes, this time of a giant flying beast.': 'Một hình ảnh khác hiện ra, lần này là một mãnh thú bay khổng lồ.',
    '"They escaped wars, poverty, suffering. The most powerful mages of this universe gave everything to become One."': '“Họ đã thoát khỏi chiến tranh, nghèo đói và khổ đau. Những pháp sư mạnh nhất vũ trụ này đã hiến dâng tất cả để trở thành Một.”',
    'A swarm of incorporeal insects surrounds the expedition.': 'Một bầy côn trùng vô hình thể bao vây đoàn thám hiểm.',
    '"You have to find a way to free it. No one deserves its destiny."': '“Các ngươi phải tìm cách giải thoát nó. Không ai đáng chịu số phận ấy.”',
    'An enormous titan, sat behind an immense forge, stares down at the expedition.': 'Một titan khổng lồ ngồi sau lò rèn đồ sộ, nhìn xuống đoàn thám hiểm.',
    '"And then, when death was abolished and defenses were lowered, the Serpent manifested in our skies, and started eating it. Forever.': '“Và rồi, khi cái chết bị xóa bỏ và mọi phòng bị hạ xuống, Xà Thần hiện thân trên bầu trời của chúng ta và bắt đầu ăn nó. Mãi mãi.',
    'The Singularity lies in a valley ahead.': 'Điểm Kỳ Dị nằm trong thung lũng phía trước.',
    'Deprived of its dreams, the Singularity twitches erratically.': 'Bị tước mất những giấc mơ, Điểm Kỳ Dị co giật hỗn loạn.',
    'The Singularity stops moving, deprived of its energy. It goes back to a peaceful sleep.': 'Điểm Kỳ Dị ngừng chuyển động vì cạn năng lượng. Nó trở lại giấc ngủ yên bình.',
    'The machine lights up, and the molten core reveals a passage to a desolate land, with a sky darkened by ominous clouds. The expedition steps through and arrives at the edge of a dilapidated village, marked by strange, unfamiliar architecture.': 'Cỗ máy bừng sáng, và lõi nóng chảy mở ra một lối đi tới vùng đất hoang tàn dưới bầu trời bị mây dữ che phủ. Đoàn thám hiểm bước qua và tới rìa một ngôi làng đổ nát mang kiến trúc xa lạ.',
    'A wave of mutated horrors surges down the road.': 'Một làn sóng quái vật đột biến tràn xuống con đường.',
    'It crushes the old man in an instant and turn toward the adventurers.': 'Nó nghiền nát ông lão trong chớp mắt rồi quay sang các mạo hiểm giả.',
    'Something else approaches, inhumanly fast.': 'Một thứ khác đang áp sát với tốc độ phi nhân.',
    'They direct their attention at the intruders.': 'Chúng chuyển sự chú ý sang những kẻ xâm nhập.',
    "The manor's security force descends from all directions.": 'Lực lượng bảo vệ trang viên đổ xuống từ mọi hướng.',
    'Instantly, they sprint down to attack.': 'Ngay lập tức, chúng lao xuống tấn công.',
    'They raise from their seats and attack.': 'Chúng đứng dậy khỏi ghế và tấn công.',
    'Rag-clad villagers glance at the newcomers and wave them away in fear. Moments later, they all retreat inside their homes.': 'Dân làng mặc giẻ rách nhìn những người mới đến rồi sợ hãi xua họ đi. Chốc lát sau, tất cả rút vào nhà.',
    'An old man emerges from one of the crumbling houses. He warns that others will come soon, then begins recounting the story of his world: a utopia turned nightmare.': 'Một ông lão bước ra từ căn nhà sắp sụp. Ông cảnh báo rằng những kẻ khác sẽ sớm tới, rồi bắt đầu kể câu chuyện về thế giới của mình: một chốn không tưởng đã hóa thành ác mộng.',
    'He speaks of the discovery of immortality, and of the mental decay triggered by the repeated return of the Black Serpent.': 'Ông kể về sự khám phá ra bất tử, và sự suy đồi tâm trí do Hắc Xà liên tục trở lại.',
    'Of the discovery of the Panacea, able to stop the decline and allowing the ruling class to cling to power indefinitely.': 'Về sự khám phá ra Thuốc Vạn Năng, thứ có thể chặn đứng suy đồi và cho phép giai cấp thống trị bám lấy quyền lực vô thời hạn.',
    'And of the lie begotten by their fear, which created a demented government guided by madness, focused on creating the most advanced forms of repression disregarding all ethics.': 'Và về lời dối trá sinh ra từ nỗi sợ, tạo nên một chính quyền điên loạn chỉ chăm chăm phát triển những hình thức đàn áp tối tân nhất, bất chấp mọi đạo đức.',
    'From behind a building, a large monster emerges along with its following.': 'Từ sau một tòa nhà, một quái vật lớn xuất hiện cùng đoàn tùy tùng.',
    'A red castle, enveloped by lightnings, looms at the horizon.': 'Một lâu đài đỏ bị sấm sét bao phủ sừng sững nơi chân trời.',
    'The adventurers continue down winding country roads, surrounded by barren fields.': 'Các mạo hiểm giả tiếp tục men theo những con đường quê ngoằn ngoèo giữa các cánh đồng cằn cỗi.',
    'The march is long and uneventful, until they spot something far away.': 'Cuộc hành quân kéo dài và yên ắng, cho tới khi họ thấy một thứ ở đằng xa.',
    'The gates of a grand manor draw near. On the front steps, a group of disfigured mutants stands guard.': 'Cổng của một trang viên đồ sộ dần hiện ra. Trên bậc thềm phía trước, một nhóm dị nhân biến dạng đang canh gác.',
    "Inside, the manor's main hall is decrepit. Piles of broken furniture are stacked against one wall.": 'Bên trong, đại sảnh trang viên đã mục nát. Những đống đồ đạc vỡ vụn chất sát một bức tường.',
    'On the wide marble staircase, more writhing masses of flesh await.': 'Trên cầu thang cẩm thạch rộng lớn, thêm nhiều khối thịt quằn quại đang chờ đợi.',
    'A long corridor stretches above the stairs. The throne room must be close.': 'Một hành lang dài trải ra phía trên cầu thang. Phòng ngai hẳn đã ở gần.',
    "At the corridor's end stands a massive cracked door, half-open.": 'Cuối hành lang là một cánh cửa đồ sộ nứt vỡ, đang hé mở.',
    'Beyond the door, the Royal Council sits around a table, strewn with rotten food and shattered bottles.': 'Sau cánh cửa, Hội Đồng Hoàng Gia ngồi quanh một chiếc bàn đầy thức ăn thối rữa và chai lọ vỡ nát.',
    'A monstrous figure wearing a rusted crown, once a man, now something else, calls for the guards. No one answers.': 'Một hình hài quái dị đội vương miện gỉ sét—từng là người, giờ đã thành thứ khác—gọi lính canh. Không ai đáp lời.',
    'The council members lie on the ground, with the mysterious technology already repairing their wounds. The adventurers start their travel back to the portal.': 'Các thành viên hội đồng nằm trên sàn, trong khi công nghệ bí ẩn đã bắt đầu chữa lành vết thương cho chúng. Các mạo hiểm giả lên đường trở lại cánh cổng.',
    'The machine lights up, and the molten core reveals a passage to the interior of a building. It is lavishly furnished and impeccably maintained, beyond the large window on the wall, the cold void of space stretches endlessly.': 'Cỗ máy bừng sáng, và lõi nóng chảy mở ra lối đi vào bên trong một tòa nhà được trang hoàng xa hoa, gìn giữ hoàn hảo. Ngoài ô cửa sổ lớn, khoảng không vũ trụ lạnh lẽo trải dài vô tận.',
    "Adventurer's HP have been replenished": 'HP của các Mạo hiểm giả đã được hồi đầy',
    'An Adventurer was resurrected': 'Một Mạo hiểm giả đã được hồi sinh',
    '"The first bearer of the curse, who doomed countless worlds to eternal hunger."': '“Kẻ đầu tiên mang lời nguyền, đã đẩy vô số thế giới vào cơn đói vĩnh hằng.”',
    '"The mother of herself; a blasphemy against life, death, and causality."': '“Người mẹ của chính mình; một sự báng bổ sự sống, cái chết và luật nhân quả.”',
    '"A being of pure burning hatred, rejected by the Otherworld out of sheer fear."': '“Một thực thể thuần hận thù cháy bỏng, bị Dị Giới ruồng bỏ chỉ vì khiếp sợ.”',
    '"Once thought to be a moon of the prosperous planet of Neferis. The inhabitants only had a couple minutes to acknowledge their mistake."': '“Từng bị lầm tưởng là mặt trăng của hành tinh Neferis phồn thịnh. Cư dân nơi đó chỉ có vài phút để nhận ra sai lầm.”',
    '"A benevolent god of enlighted people, subdued by the trickery of those hungry for power"': '“Một vị thần nhân từ của dân tộc khai sáng, bị khuất phục bởi mưu mô của những kẻ khát quyền lực.”',
    '"A wound on this universe, barely contained but never healed. Eternal glory will come to its saviour, unending suffering to everything else."': '“Một vết thương của vũ trụ, chỉ vừa đủ bị kiềm giữ nhưng chưa bao giờ lành. Vinh quang vĩnh cửu dành cho đấng cứu tinh của nó, khổ đau vô tận dành cho mọi thứ khác.”',
    '"A piece of art that sculpts itself, and you, and me, and everything else. Its downfall, the laws it forged to bind us."': '“Một tác phẩm nghệ thuật tự điêu khắc chính nó, các ngươi, ta và mọi thứ khác. Thứ hạ gục nó là những định luật do chính nó rèn nên để trói buộc chúng ta.”',
    '"Welcome, visitors, to the Tower."': '“Chào mừng những vị khách đến với Tòa Tháp.”',
    'A vision of pure terror drifts out of its cell. Darkness invades the hall.': 'Một hiện thân của nỗi kinh hoàng thuần túy trôi ra khỏi phòng giam. Bóng tối xâm chiếm đại sảnh.',
    'A mountain of cogs and cables rolls out of the cell.': 'Một ngọn núi bánh răng và dây cáp lăn ra khỏi phòng giam.',
    '"But I digress. You reached a legendary achievement not many can boast. Tales will be written about your victory. I had a lot of fun, and hope you come try again in the future!"': '“Nhưng ta lạc đề rồi. Các ngươi đã đạt kỳ tích huyền thoại mà chẳng mấy ai có thể tự hào. Chiến thắng này sẽ được viết thành truyền thuyết. Ta đã rất vui và hy vọng các ngươi sẽ trở lại thử sức trong tương lai!”',
    'After navigating countless tunnels and winding passages deep into the mines, the expedition finally arrives at a submerged lake. The suffocating darkness obscures their surroundings, but undeterred, the team presses forward, wading cautiously through the knee-deep water.': 'Sau khi vượt qua vô số đường hầm và lối đi ngoằn ngoèo sâu trong mỏ, đoàn thám hiểm cuối cùng tới một hồ nước ngập. Bóng tối nghẹt thở che khuất mọi thứ xung quanh, nhưng cả đội vẫn tiến lên, thận trọng lội qua làn nước sâu tới đầu gối.',
    'The shadow, disturbed by the light, turns with a twitching movement.': 'Cái bóng bị ánh sáng quấy nhiễu giật giật quay lại.',
    'Suddenly, several miners are encircling the group.': 'Đột nhiên, nhiều thợ mỏ bao vây cả đội.',
    'The hideous inhabitants of the temple immediately attack.': 'Những cư dân gớm ghiếc của ngôi đền lập tức tấn công.',
    'More deformed creatures swarm the team.': 'Thêm nhiều sinh vật dị dạng tràn tới cả đội.',
    "Following their leader's orders, the monstrous creatures attack.": 'Tuân lệnh thủ lĩnh, những sinh vật quái dị lao vào tấn công.',
    'The creatures notice the explorers.': 'Các sinh vật phát hiện những nhà thám hiểm.',
    'Two miners attack.': 'Hai thợ mỏ tấn công.',
    'The team is shaken by the most horrible roar they have ever heard.': 'Cả đội chấn động bởi tiếng gầm kinh hoàng nhất họ từng nghe.',
    'The expedition moves forward with caution. In the distance, the deep, haunting notes of an organ reverberate through the cavern, sending shivers down your spine. You can’t help but dread what might be hiding in the suffocating darkness.': 'Đoàn thám hiểm thận trọng tiến lên. Từ xa, âm thanh trầm u ám của đàn organ vang dội khắp hang, khiến sống lưng lạnh buốt. Không ai ngăn được nỗi sợ về thứ đang ẩn trong bóng tối nghẹt thở.',
    'Suddenly, torches reveal a hunched shadow looming over the water.': 'Đột nhiên, ánh đuốc soi rõ một cái bóng còng lưng sừng sững trên mặt nước.',
    'Wondering what miners from the centuries old expedition are doing here, the team keeps walking in the shallow waters.': 'Tự hỏi những thợ mỏ thuộc đoàn thám hiểm từ nhiều thế kỷ trước đang làm gì ở đây, cả đội tiếp tục lội qua vùng nước nông.',
    'After a moment, the sound of more footsteps splashing through the water echoes nearby.': 'Một lát sau, tiếng nhiều bước chân khuấy nước vang lên gần đó.',
    'The sound of footsteps in the water now echoes from all directions. The expedition quickens its pace.': 'Tiếng bước chân dưới nước giờ vọng tới từ mọi phía. Đoàn thám hiểm tăng tốc.',
    'A faint silhouette of a distant building appears ahead. The team sprints toward it, hoping to find shelter from the miners lurking in the shadows.': 'Bóng mờ của một công trình xa xôi hiện ra phía trước. Cả đội chạy về đó, hy vọng tránh được những thợ mỏ rình rập trong bóng tối.',
    "As the building comes into clearer view, the team realizes it's an ancient temple. It's adorned with strange, unsettling decorations. The organ sounds appear to come from within.": 'Khi công trình hiện rõ hơn, cả đội nhận ra đó là một ngôi đền cổ trang trí bằng những hình thù kỳ lạ, bất an. Tiếng organ dường như vọng ra từ bên trong.',
    'Without hesitation, the team forces open the heavy stone door and slams it shut behind them. The organ music abruptly stops.': 'Không do dự, cả đội phá mở cánh cửa đá nặng nề rồi đóng sầm lại phía sau. Tiếng organ đột ngột dừng.',
    'A door bursts open from a side of the main room.': 'Một cánh cửa bên hông chính điện bật tung.',
    "The team proceeds toward the altar at the end of the room. A tall figure, dressed in what seems like a mockery of a priest's attire, whispers rapidly in an unknown language.": 'Cả đội tiến về bàn thờ cuối phòng. Một hình người cao lớn khoác thứ y phục nhạo báng trang phục tu sĩ đang thì thầm dồn dập bằng ngôn ngữ xa lạ.',
    'Behind the altar, a wooden door bearing strange symbols stands partially open. The team proceeds through it.': 'Sau bàn thờ, một cánh cửa gỗ mang ký hiệu kỳ lạ đang hé mở. Cả đội bước qua.',
    'The door leads to a long corridor, swallowed by total darkness like the rest of the temple.': 'Cánh cửa dẫn tới một hành lang dài bị bóng tối tuyệt đối nuốt chửng như phần còn lại của ngôi đền.',
    'The corridor opens into a vast room, where cultists are immersed in some kind of ritual. A large magic portal, leading into the vast emptiness of space, is open on the roof.': 'Hành lang mở ra một căn phòng rộng lớn, nơi các giáo đồ đang chìm trong nghi lễ nào đó. Trên mái là một cổng ma thuật lớn dẫn vào khoảng không vũ trụ vô tận.',
    'Beneath the portal, an ethereal vision rests on the ground, gradually pulling small amounts of black matter from above.': 'Bên dưới cánh cổng, một hình bóng hư ảo nằm trên đất, từ từ kéo từng lượng nhỏ vật chất đen từ phía trên xuống.',
    'Without a way to close the portal, the team leaves the ancient temple.': 'Không có cách đóng cánh cổng, cả đội rời khỏi ngôi đền cổ.',
    'One of the adventurers accidentally triggers a hidden pressure plate. A trapdoor opens beneath them, and they plummet several meters, landing hard on a stone pavement.': 'Một mạo hiểm giả vô tình kích hoạt bàn ép ẩn. Cửa sập mở dưới chân khiến cả đội rơi nhiều mét và đập mạnh xuống nền đá.',
    'Unable to climb back up, the team is forced to descends into the bowels of the temple through a spiral staircase.': 'Không thể leo trở lại, cả đội buộc phải đi sâu vào lòng ngôi đền qua cầu thang xoắn.',
    'The descent lasts for minutes, then stretches into hours. The stairs appear to be carved from a single, endless stone block. The effort to create this passage must have required an unimaginable amount of resources.': 'Cuộc đi xuống kéo dài từ vài phút thành nhiều giờ. Cầu thang dường như được đục từ một khối đá duy nhất vô tận. Việc tạo ra lối đi này hẳn tiêu tốn nguồn lực không thể tưởng tượng.',
    "The team continues descending the unchanging stairs, questioning whether there’s an end in sight. Such a deep passage couldn't have been built merely to expand the temple above, but to reach a specific, previously isolated destination.": 'Cả đội tiếp tục xuống cầu thang không đổi, tự hỏi liệu có điểm cuối hay không. Một lối đi sâu thế này không thể chỉ để mở rộng ngôi đền phía trên, mà phải dẫn tới một đích đến cụ thể từng bị cô lập.',
    "As they wonder what awaits them at the bottom of the stairs, the adventurers' conversation is cut short by the sound of another set of footsteps growing closer.": 'Khi đang bàn về thứ chờ dưới đáy cầu thang, cuộc trò chuyện bị cắt ngang bởi tiếng một nhóm bước chân khác ngày càng gần.',
    'Finally, the stairs open into a short corridor.': 'Cuối cùng, cầu thang mở ra một hành lang ngắn.',
    'At the end of the corridor lies a vast, semi-spherical room. In the center, something that defies human comprehension is being fed the corpse of a massive beholder by obedient servants.': 'Cuối hành lang là một căn phòng bán cầu rộng lớn. Ở giữa, một thứ vượt ngoài hiểu biết con người đang được những kẻ hầu trung thành dâng xác của một quái nhãn khổng lồ.',
    "Shaken by the terrible monster they just vanquished, the team begins to climb the endless stairs towards the temple's entrance.": 'Bàng hoàng vì con quái vật khủng khiếp vừa đánh bại, cả đội bắt đầu leo cầu thang vô tận trở về lối vào ngôi đền.',
    "A dark dilapidated manor stands out before you. It's dimensions are modest, part of the roof has collapsed and the snow has covered the internal floor. Four tall metal coils stand at the corners, pointing directly into the sky. The expedition walks through the broken front door.": 'Một trang viên tối tăm, đổ nát hiện ra trước mắt. Quy mô của nó khiêm tốn, một phần mái đã sập và tuyết phủ kín sàn bên trong. Bốn cuộn kim loại cao đứng ở các góc, chĩa thẳng lên trời. Đoàn thám hiểm bước qua cửa chính vỡ nát.',
    'A single entity stands in the middle of the room, almost as tall as the ceiling.': 'Một thực thể đứng giữa căn phòng, cao gần chạm trần.',
    'Soldiers dressed in white and red garments are wandering aimlessly inside the room.': 'Những binh sĩ khoác y phục trắng đỏ đang lang thang vô định trong phòng.',
    'Two hooded cultists were waiting in the room. They start muttering something in an unknown language.': 'Hai giáo đồ trùm mũ đã chờ sẵn trong phòng. Chúng bắt đầu lẩm nhẩm bằng một ngôn ngữ xa lạ.',
    'The construct wakes up, and effortlessly breaks its chains with supernatural strength.': 'Cấu thể thức tỉnh và dễ dàng bẻ gãy xiềng xích bằng sức mạnh siêu nhiên.',
    'Two staircases lead to the upper floor, filled with snow and broken, old furniture.': 'Hai cầu thang dẫn lên tầng trên, nơi đầy tuyết cùng đồ đạc cũ kỹ vỡ nát.',
    'On the first floor, there seems to be nothing valuable or interesting.': 'Tầng trên dường như không có gì giá trị hay đáng chú ý.',
    'In a corner, near a frozen fireplace, the team notices a closed trapdoor. It opens without too much effort.': 'Trong một góc gần lò sưởi đóng băng, cả đội phát hiện một cửa sập đóng kín. Nó mở ra không mấy khó khăn.',
    'A narrow flight of stairs leads in the depths of the building. After minutes of walking, the team emerge in a completely different setting.': 'Một cầu thang hẹp dẫn xuống sâu trong tòa nhà. Sau nhiều phút di chuyển, cả đội bước vào một khung cảnh hoàn toàn khác.',
    'The adventurers finds themselves in a square room with four doors at the sides. The floor and walls are made of white marble.': 'Các mạo hiểm giả đứng trong căn phòng vuông với bốn cửa ở bốn phía. Sàn và tường đều làm bằng cẩm thạch trắng.',
    'The team chooses the door on the left, and find themselves in a square room identical to the previous.': 'Cả đội chọn cửa bên trái và bước vào một căn phòng vuông giống hệt phòng trước.',
    'The team chooses the door straight ahead, and find themselves in a square room identical to the previous.': 'Cả đội chọn cửa thẳng phía trước và bước vào một căn phòng vuông giống hệt phòng trước.',
    'The team chooses the door on the right, and find themselves in a square room identical to the previous.': 'Cả đội chọn cửa bên phải và bước vào một căn phòng vuông giống hệt phòng trước.',
    'This room, identical to the others, is completely empty except for a drawer in the corner. Upon it lies medical equipment and some notes on a piece of paper.': 'Căn phòng giống hệt những phòng khác và hoàn toàn trống rỗng, ngoài một ngăn tủ trong góc. Trên đó có dụng cụ y tế cùng vài ghi chép trên giấy.',
    'The notes read:\n\nExperiment n.1:\nSubjects: 2 farmers, male and female, taken last night from the village in the eartern valley. Low to moderate psyonic capabilities.\nResult: failure, two lesser titans produced.': 'Ghi chép viết:\n\nThí nghiệm số 1:\nĐối tượng: 2 nông dân, nam và nữ, bị bắt đêm qua từ ngôi làng ở thung lũng phía đông. Năng lực tâm linh thấp đến trung bình.\nKết quả: thất bại, tạo ra hai Tiểu Titan.',
    'The notes read:\n\nExperiment n.2:\nSubject: 1 merchant, male, took shelter in the upper ruins during a storm.\nResult: failure, one lesser titan produced.': 'Ghi chép viết:\n\nThí nghiệm số 2:\nĐối tượng: 1 thương nhân nam, trú trong phế tích phía trên khi bão tới.\nKết quả: thất bại, tạo ra một Tiểu Titan.',
    "The notes read:\n\nExperiment n.3:\nSubject: 1 cultist, female. Beatrix volunteered to see if magic abilities improve success rates.\nResult: failure, one lesser titan produced. Why you didn't listen…": 'Ghi chép viết:\n\nThí nghiệm số 3:\nĐối tượng: 1 nữ giáo đồ. Beatrix tình nguyện để kiểm tra liệu năng lực phép thuật có tăng tỷ lệ thành công hay không.\nKết quả: thất bại, tạo ra một Tiểu Titan. Sao cô không chịu nghe…',
    "The notes read:\n\nExperiment n.4:\nSubject: 1 traveler, male, likely a fugitive. Was found in the upper ruins with a purse of gold and no supplies.\nResult: Success! The body merged with the Primordial, its Keveral's field increased indicating a proportional increase in power.": 'Ghi chép viết:\n\nThí nghiệm số 4:\nĐối tượng: 1 lữ khách nam, có lẽ là kẻ đào tẩu. Được tìm thấy trong phế tích phía trên với túi vàng nhưng không có nhu yếu phẩm.\nKết quả: Thành công! Cơ thể đã hòa vào Nguyên Thể, trường Keveral tăng lên, cho thấy sức mạnh cũng tăng tương ứng.',
    'The notes read:\n\nExperiment n.5:\nSubject: 1 soldier, male, part of the umpteenth crusade sent by the eastern kingdoms. Low psyonic capabilities.\nResult: failure, one lesser titan produced.': 'Ghi chép viết:\n\nThí nghiệm số 5:\nĐối tượng: 1 binh sĩ nam, thuộc đạo thập tự chinh thứ vô số do các vương quốc phương đông phái tới. Năng lực tâm linh thấp.\nKết quả: thất bại, tạo ra một Tiểu Titan.',
    "The team chooses one of the doors, and find themselves in a square room. It's empty, and there are only two other doors: one locked, bearing the symbol of a skull with red eyes, the other unlocked.": 'Cả đội chọn một cánh cửa và bước vào căn phòng vuông trống rỗng. Chỉ còn hai cửa khác: một cửa khóa mang biểu tượng hộp sọ mắt đỏ, cửa kia không khóa.',
    'Without a way to open the locked door, the expedition chooses to advance through the unlocked one.\nThey find themselves in a square room, with three doors on the sides.': 'Không có cách mở cánh cửa khóa, đoàn thám hiểm chọn đi qua cửa còn lại.\nHọ bước vào một căn phòng vuông với ba cửa ở các phía.',
    'Noticing a resemblance between the symbol and the handle of the Skeleton Key, they try to see if it fits. It does! The door unlocks.': 'Nhận thấy biểu tượng giống tay cầm của Chìa Khóa Xương, họ thử tra chìa. Vừa khít! Cánh cửa được mở khóa.',
    'The next room is much bigger than the others, without any other doors and fully furnished. A dining table lies in the center, and three beds are placed against the left wall.': 'Căn phòng tiếp theo lớn hơn hẳn, đầy đủ nội thất và không có cửa nào khác. Một bàn ăn nằm giữa phòng, ba chiếc giường kê sát tường trái.',
    'The next room is perfectly circular. In the middle, a gigantic construct made of white marble is standing, surrounded by magic devices and held in place by enormous steel chains.': 'Căn phòng tiếp theo tròn hoàn hảo. Ở giữa là một cấu thể khổng lồ bằng cẩm thạch trắng, bao quanh bởi thiết bị ma thuật và bị giữ bằng những sợi xích thép đồ sộ.',
    'Victorious, the team starts their ascent towards the surface.': 'Chiến thắng, cả đội bắt đầu trở lên mặt đất.',
    'In the center of the Golden City, a dilapidated Imperial Palace overlooks the surrounding area. While this expedition is a significant deviation from your voyage to the north, it is your duty to try to rescue the Emperor of a friendly nation. Therefore, King Roderic gave your guild the order to do everything you can to bring His Majesty to safety.': 'Giữa Thành Phố Hoàng Kim, Hoàng cung Đế quốc đổ nát nhìn xuống vùng đất xung quanh. Dù cuộc thám hiểm này khiến hành trình phương bắc chệch hướng đáng kể, giải cứu Hoàng đế của một quốc gia đồng minh vẫn là bổn phận. Vì vậy, Vua Roderic đã lệnh cho bang hội làm mọi điều có thể để đưa Bệ hạ tới nơi an toàn.',
    'A crowd of enraged citizen fills the courtyard. They attack you.': 'Một đám đông dân chúng cuồng nộ tràn ngập sân trong. Chúng lao vào tấn công.',
    'Another wave comes at you with bloodshot eyes.': 'Một đợt khác với đôi mắt đỏ ngầu xông tới.',
    'Another group engages. They want your heads.': 'Một nhóm khác nhập chiến. Chúng muốn lấy đầu cả đội.',
    'A group of guards is wandering the corridors aimlessly. As soon as they see you, they engage the fight.': 'Một nhóm vệ binh lang thang vô định trong hành lang. Ngay khi nhìn thấy cả đội, chúng lập tức khai chiến.',
    'Another team of sentinels attacks you.': 'Một đội lính canh khác lao vào tấn công.',
    'The guests, probably struck by the corruption during the cursed meal, are still sitting at the table.': 'Những vị khách, có lẽ bị tha hóa trong bữa tiệc nguyền rủa, vẫn đang ngồi bên bàn.',
    'A team of palace guards is roaming before the door.': 'Một đội cận vệ hoàng cung đang tuần tra trước cánh cửa.',
    'An inhumane scream comes from above the opened door, behind the team. Looking up, a hideous creature, still dressed in royal insignia, leaps down from the ceiling.': 'Một tiếng thét phi nhân vang lên phía trên cánh cửa mở sau lưng cả đội. Nhìn lên, họ thấy một sinh vật gớm ghiếc vẫn khoác vương hiệu nhảy xuống từ trần nhà.',
    'The team reaches the entrance of the huge courtyard. The Eye above is looking interested.': 'Cả đội tới lối vào sân trong khổng lồ. Con Mắt phía trên đang chăm chú quan sát.',
    'Marble statues with golden detail stand all over the perimeter, an immortal testament of the opulence of this court.': 'Những pho tượng cẩm thạch điểm vàng đứng quanh khuôn viên, minh chứng bất diệt cho sự xa hoa của triều đình này.',
    'In the middle of the courtyard an adorned fountain, now out of function, acts as the central decoration.': 'Giữa sân là một đài phun nước trang trí cầu kỳ, giờ đã ngừng hoạt động, làm tâm điểm của quần thể.',
    'At the end of the courtyard, a wide granite staircase leads up to the entrance of the Palace.': 'Cuối sân, một cầu thang đá granite rộng dẫn lên lối vào Hoàng cung.',
    'One side of the door is halfway open. The expedition enters the palace.': 'Một cánh cửa đang hé nửa chừng. Đoàn thám hiểm tiến vào hoàng cung.',
    'On the ground, a red carpet with golden edges extends all the way through the intertwined corridors.': 'Trên sàn, tấm thảm đỏ viền vàng kéo dài xuyên qua những hành lang đan xen.',
    'The team advances through rows of marble statues, recognizing at least a couple renowned generals.': 'Cả đội tiến qua những hàng tượng cẩm thạch và nhận ra ít nhất vài vị danh tướng.',
    'At the end of the corridor, the team finds a locked door, intricately decorated but easy to break down.': 'Cuối hành lang, cả đội gặp một cánh cửa khóa chặt, trang trí tinh xảo nhưng không khó phá.',
    'The adventurers find themselves in a large dining room, with a long laden table.': 'Các mạo hiểm giả bước vào một phòng tiệc lớn với chiếc bàn dài đầy thức ăn.',
    'Looking at the table, they notice the food is black with mold: it must have lied there for weeks.': 'Quan sát chiếc bàn, họ nhận ra thức ăn đã đen vì nấm mốc; hẳn chúng nằm đó nhiều tuần.',
    'At the end of the room, an open door leads to a short corridor. It leads to a single door, at its end.': 'Cuối căn phòng, một cửa mở dẫn vào hành lang ngắn với duy nhất một cánh cửa ở tận cùng.',
    'The door bears the seal of the Clovis family. It is closed, but unlocked.': 'Cánh cửa mang ấn của gia tộc Clovis. Nó đóng nhưng không khóa.',
    "The open door reveals the Emperor's Throne Room. It has been thrashed, without a single furniture being intact or in it's supposed place.": 'Cánh cửa mở ra Phòng Ngai của Hoàng đế. Nơi này bị đập phá tan hoang, không món nội thất nào còn nguyên vẹn hay nằm đúng vị trí.',
    'The golden throne, still in its place, is empty.': 'Ngai vàng vẫn ở nguyên vị trí nhưng trống không.',
    'With the Emperor finally at rest, the team leaves the forsaken palace to report the events to the King.': 'Khi Hoàng đế cuối cùng đã được yên nghỉ, cả đội rời hoàng cung bị ruồng bỏ để báo cáo mọi chuyện với Nhà vua.',
    "After days of travels to the far East region of the Sha'huri desert, the colossal silhouette of a pyramid emerges from the horizon. Despite the current events its condition seems pristine, its apex still glistening with a golden sheen.": 'Sau nhiều ngày đi tới vùng cực đông của sa mạc Sha\'huri, bóng dáng khổng lồ của một kim tự tháp hiện lên nơi chân trời. Bất chấp những biến cố hiện tại, công trình vẫn nguyên vẹn, đỉnh tháp còn lấp lánh ánh vàng.',
    "A small Sha'huri group, likely standing guard to the sacred site, spots the team.": 'Một nhóm Sha\'huri nhỏ, có lẽ đang canh giữ thánh địa, phát hiện cả đội.',
    'The ancient defense system activates once again, and warriors emerge from the sand. They look way more threatening than the ones you have met before.': 'Hệ thống phòng vệ cổ xưa lại kích hoạt, các chiến binh trồi lên từ cát. Chúng trông đáng sợ hơn hẳn những kẻ cả đội từng gặp.',
    'Another wave of statues emerges from the sand, still gaining consistency at the time they first strike you.': 'Một đợt tượng khác trồi lên từ cát, thân thể còn đang kết đặc khi chúng tung đòn đầu tiên.',
    'The relentless stream of sentient sand keeps coming without a break.': 'Dòng cát có tri giác không ngừng tràn tới, không cho cả đội nghỉ lấy một nhịp.',
    "In the middle of the corridor, a huge figure is standing guard. It is unlike any Sha'huri warrior you have seen before: height reaching almost four meters, wielding four swords, one for each of its hands.": 'Giữa hành lang, một hình bóng khổng lồ đang đứng canh. Hắn khác mọi chiến binh Sha\'huri từng thấy: cao gần bốn mét, bốn tay cầm bốn thanh kiếm.',
    'In the chamber, right at the center, a creature of unfathomable origin is standing perfectly still. It is unlike anything the team has seen before, inspiring deep rooted awe and overwhelming terror at the same time. When its eye opens, everyone present feels like their very soul was being peered into.': 'Ngay giữa mật thất, một sinh vật có nguồn gốc không thể thấu hiểu đứng bất động tuyệt đối. Nó khác mọi thứ cả đội từng thấy, vừa khơi dậy lòng kính sợ sâu sắc vừa gieo nỗi kinh hoàng choáng ngợp. Khi con mắt của nó mở ra, tất cả đều cảm thấy linh hồn mình đang bị soi thấu.',
    'The adventurers navigate through the dunes, their boots sinking into the warm sand. Slowly, the pyramid is getting closer.': 'Các mạo hiểm giả băng qua những đụn cát, đôi ủng lún vào lớp cát ấm. Kim tự tháp chậm rãi hiện gần hơn.',
    'The rhythmic crunch of footsteps harmonizes with the desert winds, as the expedition starts to make out the intricate block pattern that makes up the building.': 'Tiếng bước chân lạo xạo hòa cùng gió sa mạc khi đoàn thám hiểm bắt đầu nhìn rõ hoa văn ghép khối phức tạp tạo nên công trình.',
    'The sound of blaring trumpets is heard in the distance, and the sand starts twisting below your feet. This is unlikely to be a good sign.': 'Tiếng kèn chói tai vang lên từ xa, cát dưới chân bắt đầu xoáy chuyển. Đây khó có thể là điềm lành.',
    "Sha'huri deterrent system activated, threat level: EXTINCTION.": 'Hệ thống răn đe Sha\'huri đã kích hoạt, mức đe dọa: TUYỆT DIỆT.',
    'The trumpet sound finally stop, and the sand is once again at rest.': 'Tiếng kèn cuối cùng cũng dừng, cát một lần nữa lắng yên.',
    'After some more minutes, the team is getting close to the pyramid. As they advance, the immense size of the construction becomes more apparent.': 'Sau thêm vài phút, cả đội đã tới gần kim tự tháp. Càng tiến bước, quy mô đồ sộ của công trình càng hiện rõ.',
    'The expedition finally reaches the pyramid base. There is no door, just a wide opening on one of the sides that leads to a long corridor. Light is coming from ardent torches that lines the two walls.': 'Đoàn thám hiểm cuối cùng tới chân kim tự tháp. Không có cửa, chỉ có một lối mở rộng bên sườn dẫn vào hành lang dài, được soi sáng bởi những ngọn đuốc rực lửa dọc hai tường.',
    'The team walks deeper into the corridor that seems to never end, being thankful for the torches that make the travel less frightening.': 'Cả đội đi sâu hơn vào hành lang tưởng như vô tận, thầm biết ơn những ngọn đuốc khiến hành trình bớt đáng sợ.',
    'A giant stone door blocks the path of the expedition. It is sealed shut, and bears the symbol of a triangle with an open eye inscribed inside.': 'Một cánh cửa đá khổng lồ chắn lối đoàn thám hiểm. Nó bị niêm kín, mang biểu tượng tam giác với con mắt mở khắc bên trong.',
    "Together, the adventurers push the door with all their strength. However, it doesn't seem to move. [Global Constitution required: 200]": 'Các mạo hiểm giả hợp sức dùng toàn bộ sức mạnh đẩy cửa, nhưng nó không hề nhúc nhích. [Tổng Thể chất yêu cầu: 200]',
    'Together, the adventurers push the door with all their strength. Slowly, it opens wide to reveal a single, inner chamber.': 'Các mạo hiểm giả hợp sức dùng toàn bộ sức mạnh đẩy cửa. Nó chậm rãi mở rộng, để lộ một mật thất duy nhất.',
    'Cracks starts forming on the alien being surface, as its eye look around frantically, almost scared. Suddenly, it explodes in a thousand pieces, leaving almost no trace. Almost, because on the ground lies a strange trinket…': 'Những vết nứt bắt đầu hình thành trên bề mặt sinh vật xa lạ khi con mắt nó hoảng loạn nhìn quanh, gần như sợ hãi. Đột nhiên, nó nổ tung thành ngàn mảnh và hầu như không để lại dấu vết. Hầu như—bởi trên mặt đất còn nằm một món trang sức kỳ lạ…',
    'Deep within the Enchanted Forest, after opening your way through a mostly invisible, secluded path, the expedition finds themselves in front of an eerie pond. It looks quite peaceful: the creatures of the forest seem to have given respite from their relentless chase, and the atmosphere gives off magic vibes. It must have something to do with the extremely vivid color, or the perceived viscosity of the water in the pond, almost too thick.': 'Sâu trong Khu Rừng Phù Phép, sau khi mở đường qua một lối mòn hẻo lánh gần như vô hình, đoàn thám hiểm đứng trước một hồ nước kỳ quái. Nơi đây trông khá yên bình: các sinh vật trong rừng dường như đã tạm ngừng cuộc truy đuổi không khoan nhượng, còn bầu không khí phảng phất ma lực. Có lẽ nguyên nhân là màu nước rực rỡ khác thường, hoặc cảm giác nước trong hồ sánh đặc đến mức gần như quá quánh.',
    'The slimes attack!': 'Lũ slime tấn công!',
    'The slimes jump down from the trees, as the team prepares for the fight.': 'Lũ slime nhảy xuống từ trên cây khi cả đội chuẩn bị chiến đấu.',
    'Surrounded, the adventurers raise their weapons once again.': 'Bị bao vây, các mạo hiểm giả một lần nữa giương vũ khí.',
    'With unnatural agility, it makes a higher leap and lands exactly in front of the team.': 'Với sự nhanh nhẹn phi tự nhiên, nó bật cao rồi đáp xuống ngay trước mặt cả đội.',
    'After removing the last remaining twigs obstructing the way, the team moves towards the pond to investigate.': 'Sau khi dọn những cành cây cuối cùng chắn lối, cả đội tiến về phía hồ để điều tra.',
    "Almost invisible below the body of water, creatures unlike anything they've seen before swarm the expedition.": 'Gần như vô hình dưới mặt nước, những sinh vật chưa từng thấy trước đây tràn lên bao vây đoàn thám hiểm.',
    'Turning around, the team discovers that the trees around the pond are swarming with slimes, coming out of their hideouts to aid their companions.': 'Quay lại, cả đội phát hiện cây cối quanh hồ đầy slime đang chui khỏi nơi ẩn nấp để trợ giúp đồng loại.',
    'Without a break, the neverending stream of slimes keep coming out of the water and down from the trees.': 'Không một phút nghỉ, dòng slime bất tận tiếp tục trồi khỏi mặt nước và đổ xuống từ trên cây.',
    'In the distance, thumping sounds of growing intensity make the leaves tremble on the branches. The army of slimes stopped their assault, and watches the group from afar.': 'Ở phía xa, tiếng thình thịch ngày càng mạnh làm lá cây rung lên trên cành. Đạo quân slime ngừng tấn công và quan sát cả đội từ xa.',
    'As the thumping increases, the adventurers spot something in the distance: an iridescent mass, adorned with royal attire, is slowly jumping towards the group.': 'Khi tiếng thình thịch dồn dập hơn, các mạo hiểm giả trông thấy một khối óng ánh khoác vương phục đang chậm rãi nhảy về phía họ.',
    "The King of the Slimes slowly loses consistency, becoming almost liquid. It seeps into the ground like rainwater leaving no trace, while the other slimes scatter in panic. You wonder if these creatures were peaceful before the corruption, and will make sure to report your findings to the kingdom's taxonomists to understand more of their nature.": 'Vua Slime từ từ mất kết cấu và gần như hóa lỏng. Nó thấm xuống đất như nước mưa, không để lại dấu vết, trong khi những slime khác hoảng loạn tản đi. Cả đội tự hỏi liệu các sinh vật này có từng hiền hòa trước khi bị tha hóa hay không, và sẽ báo cáo phát hiện cho các nhà phân loại học của vương quốc để hiểu rõ hơn bản chất của chúng.',
    'The team crosses the dark entrance to the ancient Catacombs of the Eternal battlefield. This is an ancient place where, after the agreement of the year fourteen of the eternal war, both factions can give their fallen high-ranking fighters a worthy burial.\nStrangely enough, instead of finding a quiet place, horrible sounds are coming from the lower levels…': 'Cả đội bước qua lối vào tối tăm dẫn tới Hầm Mộ cổ xưa của Chiến Trường Vĩnh Hằng. Đây là nơi mà sau hiệp ước năm thứ mười bốn của cuộc chiến vĩnh cửu, cả hai phe đều có thể an táng trọng thể những chiến binh cấp cao đã ngã xuống.\nKỳ lạ thay, thay vì một nơi yên tĩnh, những âm thanh kinh hoàng lại vọng lên từ các tầng sâu…',
    "Without its master's magic to hold the pieces together, the Necrolith crumbles to dust.": 'Không còn ma lực của chủ nhân giữ các mảnh xương kết lại, Cự Tượng Cốt Linh vỡ vụn thành bụi.',
    'From a nearby wall, reanimated bodies crawl towards the expedition': 'Từ một bức tường gần đó, những thi thể được hồi sinh bò về phía đoàn thám hiểm',
    'A nearby wooden door is shattered into a thousand splinters by a towering presence.': 'Một hiện diện cao lớn đập cánh cửa gỗ gần đó vỡ thành ngàn mảnh.',
    'In front of them, an undead clad in a golden armor orders its followers into the battle. A curious display of sentience for an undead, the team notes.': 'Phía trước, một xác sống khoác giáp vàng ra lệnh cho thuộc hạ xông vào trận. Cả đội nhận thấy đó là biểu hiện ý thức kỳ lạ đối với một xác sống.',
    'From the darkness, the monsters start running at the adventurers.': 'Từ trong bóng tối, lũ quái vật bắt đầu lao về phía các mạo hiểm giả.',
    'A second wave of undead leaves the team no respite.': 'Đợt xác sống thứ hai không cho cả đội một phút nghỉ ngơi.',
    'Inside the crypt, a decrepit skeleton holding a metal scepter lets out a frightening scream.': 'Bên trong hầm mộ, một bộ xương mục nát cầm quyền trượng kim loại thét lên ghê rợn.',
    'The adventurers take the first step beyond the open door.': 'Các mạo hiểm giả bước bước đầu tiên qua cánh cửa đang mở.',
    'Piles of skulls and bones are piled up on the sides, covering the walls of the corridor.': 'Những đống sọ và xương chất cao hai bên, phủ kín tường hành lang.',
    'The air becomes more chilling, the corridor darker. The noises from below are almost unbearable.': 'Không khí ngày càng lạnh buốt, hành lang càng lúc càng tối. Âm thanh từ bên dưới gần như không thể chịu nổi.',
    'The corridor ceiling gets a bit lower.': 'Trần hành lang dần hạ thấp.',
    'The group resumes their expedition, taking a flight of stairs down to the lower levels.': 'Cả đội tiếp tục cuộc thám hiểm, men theo một cầu thang xuống các tầng sâu hơn.',
    'The stairs end, and the corridor opens into a large, dark hall.': 'Cầu thang kết thúc, hành lang mở ra một đại sảnh rộng lớn và tối tăm.',
    'A voice of unknown origin, as dry as these putrid walls, echoes in the hall. It is not loud enough to understand.': 'Một giọng nói không rõ nguồn gốc, khô khốc như những bức tường mục rữa, vọng khắp đại sảnh. Nó quá nhỏ để có thể nghe rõ.',
    'In the center of the circular hall, a pillar made of bones holds up the tall ceiling.': 'Giữa đại sảnh hình tròn, một cột trụ bằng xương chống đỡ mái vòm cao.',
    'At the end of the now empty hall, an adorned iron door blocks the path.': 'Cuối đại sảnh giờ đã trống không, một cánh cửa sắt trang trí cầu kỳ chắn lối.',
    'The voice speaks again, this time a bit clearer. It says "Come forth, my children. Come join my ranks."': 'Giọng nói lại vang lên, lần này rõ hơn đôi chút: “Tiến lên, các con của ta. Hãy gia nhập hàng ngũ của ta.”',
    'The door is unlocked, and reveals a circular crypt.': 'Cánh cửa được mở khóa, để lộ một hầm mộ hình tròn.',
    "The room is now empty, and the screams have stopped. There isn't really a way to kill a lich, but it should stay quiet for a while. The team turns back and reaches for the surface.": 'Căn phòng giờ đã trống, những tiếng thét cũng im bặt. Thực ra không có cách nào giết hẳn một lich, nhưng nó sẽ yên lặng được một thời gian. Cả đội quay lại và tiến lên mặt đất.',
    'Beneath the fiery volcano, a network of tunnels descends into the planet\'s depths. The heat is unbearable, yet the expedition presses on with unwavering determination.': 'Bên dưới ngọn núi lửa rực cháy, một mạng lưới đường hầm đổ sâu vào lòng hành tinh. Sức nóng không thể chịu nổi, nhưng đoàn thám hiểm vẫn tiến bước với quyết tâm không lay chuyển.',
    'A faint light pierces the darkness ahead, suggesting the Core is near.': 'Một tia sáng mờ xuyên qua bóng tối phía trước, báo hiệu Lõi đang ở gần.',
    'A whisper echoes through the tunnels, resembling people arguing in an unintelligible language.': 'Một tiếng thì thầm vọng qua đường hầm, tựa như nhiều người đang tranh cãi bằng thứ ngôn ngữ không thể hiểu nổi.',
    'The light grows brighter, intensifying along with the heat.': 'Ánh sáng ngày càng rực hơn, sức nóng cũng tăng theo.',
    'Rounding a corner, the expedition enters a vast cavern. In the distance, the core reveals itself with an eerie, unnatural purple light.': 'Vòng qua một khúc cua, đoàn thám hiểm bước vào hang động rộng lớn. Ở phía xa, Lõi lộ diện trong thứ ánh sáng tím kỳ quái, phi tự nhiên.',
    'Before the chasm, three colossal, nightmarish entities resembling the Seer\'s true form stand guard to an arcane machine.': 'Trước vực sâu, ba thực thể khổng lồ ác mộng mang hình hài giống chân thân của Nhà Tiên Tri đang canh giữ một cỗ máy bí thuật.',
    '“Your quest ends here, Adventurers.”': '“Hành trình của các ngươi kết thúc tại đây, hỡi các Mạo hiểm giả.”',
    'The long battle has left the team exhausted, and barely alive.': 'Trận chiến kéo dài khiến cả đội kiệt sức và chỉ còn thoi thóp.',
    'The adventurers decide that the machine should not be touched. King Roderic will be informed of its presence, and a more competent research team will likely be dispatched.': 'Các mạo hiểm giả quyết định không chạm vào cỗ máy. Vua Roderic sẽ được báo về sự hiện diện của nó, và một nhóm nghiên cứu đủ năng lực hơn có lẽ sẽ được cử tới.',
    'The guild\'s expedition is over. They slowly ascend towards the surface, eager to see the sunlight once more.': 'Cuộc thám hiểm của bang hội đã kết thúc. Họ chậm rãi trở lại mặt đất, nóng lòng được nhìn thấy ánh mặt trời một lần nữa.',
    'The expedition is preparing to enter the dungeon.': 'Đội thám hiểm đang chuẩn bị tiến vào hầm ngục.',
    'The party won the fight.': 'Đội đã chiến thắng.',
    'The party was defeated.': 'Đội đã bị đánh bại.',
    'The party searched the room.': 'Đội đã lục soát căn phòng.',
    'The expedition spotted a massive, pale blue structure at the edge of the Barren Wastelands. After their report, a team is assigned to investigate.': 'Đoàn thám hiểm phát hiện một kiến trúc xanh nhạt khổng lồ ở rìa Hoang Địa Cằn Cỗi. Sau khi nhận báo cáo, một đội được cử đi điều tra.',
    'With its source of power irreversibly compromised, the G.C.S.S. deactivates.': 'Nguồn năng lượng bị phá hủy không thể phục hồi khiến G.C.S.S. ngừng hoạt động.',
    'Two flying devices spot the team; one immediately flies off.': 'Hai thiết bị bay phát hiện cả đội; một chiếc lập tức bay đi.',
    'A nearby patrol shifts its focus toward the team.': 'Một đội tuần tra gần đó chuyển sự chú ý sang cả đội.',
    'The first wave reaches the team and attacks with full force.': 'Đợt quân đầu tiên đuổi kịp và dốc toàn lực tấn công cả đội.',
    'Another wave prepares to halt the advance.': 'Một đợt quân khác chuẩn bị chặn bước tiến của cả đội.',
    'The relentless celestial attack continues.': 'Cuộc tấn công không ngừng của quân Thiên Giới tiếp diễn.',
    'A massive ship hovers overhead, as ground units leap several meters to the ground.': 'Một phi thuyền khổng lồ lơ lửng phía trên, trong khi các đơn vị mặt đất nhảy xuống từ độ cao vài mét.',
    'More ships approach, accompanied by ground support.': 'Nhiều phi thuyền khác đang tiến đến cùng lực lượng yểm trợ mặt đất.',
    'Two unknown devices on the side of the door are armed.': 'Hai thiết bị lạ hai bên cánh cửa được kích hoạt.',
    'Two devices, identical to the ones encountered before, are activated.': 'Hai thiết bị giống hệt những chiếc từng gặp trước đó được kích hoạt.',
    'He flips a switch and charges toward the adventurers.': 'Hắn gạt một công tắc rồi lao về phía các mạo hiểm giả.',
    'As they approach, it becomes clear the structure is of artificial origin.': 'Khi đến gần, cả đội nhận ra kiến trúc này rõ ràng là một tạo vật nhân tạo.',
    'Beneath the structure, hundreds of thousands of celestial soldiers stand ready in the distance.': 'Bên dưới kiến trúc, hàng trăm nghìn binh sĩ Thiên Giới đang đứng chờ ở phía xa.',
    'Suddenly, the enemy ranks stir, metal clattering as they advance toward your position!': 'Đột nhiên hàng ngũ địch chuyển động, tiếng kim loại va nhau vang lên khi chúng tiến về vị trí của đội!',
    'The expedition hurries across the barren landscape, skipping through the ever present banshee burrows.': 'Đoàn thám hiểm vội vã băng qua miền đất cằn cỗi, luồn qua những hang Banshee hiện diện khắp nơi.',
    'As the celestial structure looms closer, the team shivers, awestruck by its immense size.': 'Kiến trúc Thiên Giới càng lúc càng gần; cả đội rùng mình kinh ngạc trước kích thước đồ sộ của nó.',
    'Chased by the entire celestial army, the team sharply veers into a narrow passage, hoping to delay the advance.': 'Bị cả đạo quân Thiên Giới truy đuổi, đội đột ngột rẽ vào một lối hẹp với hy vọng làm chậm bước tiến của chúng.',
    'After a few minutes of running, the metallic clatter of the celestial horde fades a little, and the team spots the exit of the passage.': 'Sau vài phút chạy, tiếng kim loại của đạo quân Thiên Giới nhỏ dần và cả đội nhìn thấy lối ra khỏi đường hẹp.',
    'The expedition is now no more than a minute away from the building.': 'Đoàn thám hiểm giờ chỉ còn cách công trình chưa đầy một phút.',
    'Several ropes hang from a metal platform above. The horde is closing in.': 'Vài sợi dây thừng buông xuống từ bệ kim loại phía trên. Đạo quân đang áp sát.',
    'With the whole Celestial Army at your heels, the team manage to climb onto the structure.': 'Với cả đạo quân Thiên Giới bám sát phía sau, cả đội đã leo được lên công trình.',
    "Inside, the structure is even more alien: vast, empty spaces with ceilings soaring tens of meters high and architecture unlike anything they've ever seen.": 'Bên trong còn xa lạ hơn: những khoảng không rộng lớn trống rỗng, trần cao hàng chục mét và lối kiến trúc chưa từng thấy.',
    'In front, an imposing metal door blocks the path.': 'Phía trước, một cánh cửa kim loại uy nghi chắn lối.',
    'Behind the door is a large round room, with no other exits in sight.': 'Sau cánh cửa là một căn phòng tròn lớn, không thấy bất kỳ lối ra nào khác.',
    'In the center, a lone lever is present. When pulled, it lifts the team to the upper levels.': 'Ở chính giữa chỉ có một cần gạt. Khi kéo xuống, nó đưa cả đội lên những tầng trên.',
    'A small atrium lies ahead, with a door similar to the one they forced open earlier.': 'Phía trước là một tiền sảnh nhỏ với cánh cửa giống cánh cửa họ vừa phá trước đó.',
    'A long corridor leads to a round room filled with switches and levers.': 'Một hành lang dài dẫn đến căn phòng tròn đầy công tắc và cần gạt.',
    'In the center of the room, a towering humanoid rises from the command chair.': 'Giữa căn phòng, một hình người cao lớn đứng dậy khỏi ghế chỉ huy.',
    "Cracks begin to form on the structure's ceiling, suggesting the triggering of some safety mechanism.": 'Các vết nứt bắt đầu xuất hiện trên trần công trình, báo hiệu một cơ chế an toàn nào đó đã được kích hoạt.',
    'As the room begins to collapse, someone pulls a lever on the right wall. In an instant, the team is teleported to high ground miles away, where they watch the building crumble from a safe distance.': 'Khi căn phòng bắt đầu sụp đổ, một người kéo cần gạt trên bức tường bên phải. Trong chớp mắt, cả đội được dịch chuyển đến vùng đất cao cách đó hàng dặm và an toàn nhìn công trình tan rã.',
    'A mountain of writhing souls stands tall outside the Obsidian Mines exit. Their degree of paleness vary considerably, from the newly added soldiers to those trapped there for millennia. At the summit, the wicked seer performs its ritual.': 'Một ngọn núi gồm những linh hồn quằn quại sừng sững bên ngoài lối ra của Mỏ Hắc Diện Thạch. Sắc độ nhợt nhạt của chúng rất khác nhau, từ những binh sĩ vừa bị nuốt vào cho đến những kẻ đã mắc kẹt suốt hàng thiên niên kỷ. Trên đỉnh núi, tên tiên tri độc ác đang cử hành nghi lễ.',
    'All around the team, the spirits of long forgotten warriors emerge from the mountain.': 'Khắp xung quanh đội, linh hồn của những chiến binh đã bị lãng quên từ lâu trồi ra khỏi ngọn núi.',
    "From below the team's feet, ghastly arms are digging upwards.": 'Từ dưới chân cả đội, những cánh tay ma quái đang đào ngược lên.',
    'Knights with vitreous eyes advance towards the expedition.': 'Những hiệp sĩ với đôi mắt vô hồn như thủy tinh tiến về phía đoàn thám hiểm.',
    'The unsteady ethereal blob around the team forms a few, definite hateful figures.': 'Khối linh thể chập chờn quanh đội dần kết thành vài hình hài căm hận rõ rệt.',
    'The restless mountain materializes again in the form of long forgotten souls, forgotten for millennia.': 'Ngọn núi không yên lại hiện hình thành những linh hồn đã bị lãng quên suốt hàng thiên niên kỷ.',
    '"You cowardly insects dare speak to me while i\'m performing the holy ritual? Die, and nourish the Mountain!"': '“Lũ côn trùng hèn nhát các ngươi dám lên tiếng khi ta đang cử hành nghi lễ thiêng liêng sao? Chết đi, và trở thành dưỡng chất cho Ngọn Núi!”',
    'The team takes a deep breath and begins the dreadful ascent.': 'Cả đội hít một hơi thật sâu và bắt đầu cuộc leo lên kinh hoàng.',
    'The grotesque mass below, stretching endlessly into the ashen sky, provides an extremely unstable terrain.': 'Khối vật chất dị dạng bên dưới kéo dài bất tận vào bầu trời tro xám, tạo thành một địa hình vô cùng bất ổn.',
    'The adventurers feet plunge into undulating sea of spectral forms with every new step.': 'Mỗi bước đi lại khiến chân các mạo hiểm giả lún sâu vào biển hình hài ma quái đang cuộn sóng.',
    'The team presses through the swirling miasma of hate and resentment, forging a new path with only determination as their tool.': 'Cả đội ép mình xuyên qua màn chướng khí căm hận và oán giận đang xoáy cuộn, dùng duy nhất ý chí để mở một con đường mới.',
    'The screams of agony around the group almost breaks the sanity of the climbers.': 'Những tiếng gào đau đớn quanh đội gần như nghiền nát lý trí của những người đang leo lên.',
    'In the distance, a colossal wraith formed from the amalgamation of countless souls watches the surrounding.': 'Ở phía xa, một bóng ma khổng lồ kết thành từ vô số linh hồn đang quan sát xung quanh.',
    'The team hides for some minutes waiting for the gigantic threat to direct its gaze elsewhere.': 'Cả đội ẩn mình vài phút, chờ mối đe dọa khổng lồ chuyển ánh nhìn sang nơi khác.',
    'Ghastly appendages try to pull the explorers down into the throbbing mass at every occasion.': 'Những chi ma quái không ngừng tìm cơ hội kéo các nhà thám hiểm xuống khối linh hồn đang co bóp.',
    'The expedition resumes, with the pillar on the summit now closer than ever.': 'Đoàn thám hiểm tiếp tục tiến bước; cột sáng trên đỉnh giờ đã gần hơn bao giờ hết.',
    'The traitorous Seer, now serving its true master, exits his trance-like state to confront the adventurers.': 'Tên Tiên Tri phản bội, giờ đang phụng sự chủ nhân thật sự, thoát khỏi trạng thái nhập định để đối đầu với các mạo hiểm giả.',
    '"You will not break the Astral Graft. Witness my eternal form, and perish in the fire of a thousand suns!"': '“Các ngươi sẽ không phá được Mối Ghép Tinh Tú. Hãy chứng kiến hình hài vĩnh cửu của ta, rồi tiêu vong trong ngọn lửa của ngàn mặt trời!”',
    '"Master, i… am sorry for this cycle. I cannot manifest the Graft anymore. The next one will be stronger…"': '“Chủ nhân, con… xin lỗi vì chu kỳ này. Con không thể hiện thân Mối Ghép thêm nữa. Chu kỳ kế tiếp sẽ mạnh hơn…”',
    'The purple pillar ascending into the sky instantly snaps, twisting like a cut appendage. As the mountain quickly deflates, the clouds start dissipating showing the stars behind. Two colossal maws, each bigger than a whole mountain, close violently around the body of the Seer. They slowly retreat into the vastness of the night, leaving behind nothing but a small, unremarkable red book.': 'Cột sáng tím vươn lên trời lập tức đứt gãy, quằn quại như một chi thể vừa bị chặt lìa. Khi ngọn núi nhanh chóng xẹp xuống, mây tan dần để lộ những vì sao phía sau. Hai chiếc hàm khổng lồ, mỗi chiếc còn lớn hơn cả một ngọn núi, hung bạo khép lại quanh thân xác tên Tiên Tri. Chúng chậm rãi rút vào màn đêm vô tận, chỉ để lại một cuốn sách đỏ nhỏ bé, chẳng có gì nổi bật.',
    "In front of the expedition stands out the endless mass of brambles that marks the southern end of the civilized world. These areas harbor an aggressive fauna, poorly studied by a few brave explorers. As if the danger wasn't enough, a mild earthquake is constantly shaking the vegetation…": 'Trước mặt đoàn thám hiểm là biển bụi gai bất tận, đánh dấu rìa phía nam của thế giới văn minh. Khu vực này là nơi trú ngụ của hệ động vật hung dữ mà chỉ vài nhà thám hiểm gan dạ từng nghiên cứu sơ sài. Như thể hiểm nguy vẫn chưa đủ, một trận động đất nhẹ còn không ngừng lay chuyển cả khu rừng…',
    'The adventurers cut a thick branch full of spikes before proceeding to the next areas': 'Các mạo hiểm giả chặt đứt một cành cây dày đặc gai trước khi tiến sang khu vực kế tiếp.',
    'Carefully enough, the expedition crosses a small muddy stream': 'Đoàn thám hiểm cẩn thận vượt qua một dòng suối nhỏ lầy lội.',
    "The sound of cracking trees alert the team. It's probably a wise idea to head in the opposite directions.": 'Tiếng cây gãy răng rắc khiến cả đội cảnh giác. Đi theo hướng ngược lại có lẽ là lựa chọn khôn ngoan.',
    'A thick curtain of dead branches blocks the path. The team has to find a way around it.': 'Một bức màn cành khô dày đặc chắn ngang đường. Cả đội phải tìm lối vòng qua.',
    'A patch of trees in the distance suddenly falls, swallowed by the terrain below. The team hastens its pace.': 'Một mảng cây phía xa đột ngột đổ sụp và bị mặt đất bên dưới nuốt chửng. Cả đội vội tăng tốc.',
    "The expedition passes a huge tree growing around long dead remains, but you can't tell the species of the unfortunate victim.": 'Đoàn thám hiểm đi ngang một cây khổng lồ mọc quấn quanh bộ hài cốt đã chết từ lâu, nhưng không thể xác định loài của nạn nhân xấu số.',
    'Around the corner, several cracked eggs as big as an average person lie on the ground.': 'Qua khúc quanh, vài quả trứng nứt vỡ lớn bằng một người bình thường nằm rải trên mặt đất.',
    'A natural bridge of brambles allows to safely cross a large, deep creek running through the forest.': 'Một cây cầu bụi gai tự nhiên giúp cả đội an toàn vượt qua dòng suối lớn và sâu chạy xuyên khu rừng.',
    'The constant earthquake increases for a moment, prompting the expedition to run away from the tallest trees.': 'Cơn địa chấn liên tục bất ngờ mạnh lên, buộc đoàn thám hiểm phải chạy xa khỏi những cây cao nhất.',
    'The expedition carefully advance through a patch of shaking trees.': 'Đoàn thám hiểm thận trọng tiến qua một vùng cây cối đang rung chuyển.',
    'Silently, something descends from the branches above.': 'Không một tiếng động, thứ gì đó hạ xuống từ những cành cây phía trên.',
    'In a nearby clearing surrounded by spikes, enemies are alerted by the team steps.': 'Trong khoảng rừng trống gần đó được gai nhọn bao quanh, kẻ địch bị tiếng bước chân của cả đội đánh động.',
    'With a swift knife strike, the team cuts a spike curtain that reveals the hostile creatures behind.': 'Bằng một nhát dao nhanh gọn, cả đội cắt toạc màn gai và để lộ những sinh vật thù địch phía sau.',
    'Something is following the team. The escape is interrupted by a mass of brambles that would take too long to cut.': 'Thứ gì đó đang bám theo cả đội. Đường rút bị chặn bởi một khối bụi gai quá lớn để chặt kịp.',
    'Wild creatures crawl out from below the side of a collapsed path.': 'Những sinh vật hoang dã bò ra từ mép dưới của con đường đã sụp đổ.',
    'A huge bramble mass, shaken by the constant earthquake, falls from the branches above.': 'Một khối bụi gai khổng lồ bị địa chấn liên tục rung lắc và rơi xuống từ những cành cây phía trên.',
    'The team notices a white haired Dryad sitting on a nearby branch, staring at them while whispering the formula of an unknown spell.': 'Cả đội nhận ra một Mộc tinh tóc trắng ngồi trên cành cây gần đó, vừa nhìn chằm chằm vào họ vừa thì thầm công thức của một phép thuật lạ.',
    'The ground below collapses into the maws of a colossal Wurm. Adventurers must get out of the way, and fast!': 'Mặt đất bên dưới sụp vào hàm của một Cự Trùng khổng lồ. Các mạo hiểm giả phải tránh ra ngay lập tức!',
    'The Primeval Wurm stands as tall as a mountain. It tries to devour the team with unexpected speed.': 'Cự Trùng Nguyên Thủy cao sừng sững như một ngọn núi. Nó lao tới nuốt chửng cả đội với tốc độ không ngờ.',
    'A desolate land stretches as far as the eye can see. These are the hunting grounds of the Banshees, ruthless armored beasts known for their solitary nature. However, something else is going on: constructs resembling flying eyes roam the skies, while the horizon looks like a sea of flames.': 'Một vùng đất hoang tàn trải dài tới tận chân trời. Đây là bãi săn của những Banshee, loài mãnh thú bọc giáp tàn nhẫn nổi tiếng sống đơn độc. Tuy nhiên, nơi này còn có chuyện khác: những cấu thể giống mắt bay tuần tra trên trời, còn đường chân trời trông như một biển lửa.',
    "Far away, a Banshee crawls out of the ground and leaps to an unsuspecting invader trying to burn some remains. It's over before he even notices the attacker.": 'Ở phía xa, một Banshee bò lên khỏi mặt đất rồi vồ lấy kẻ xâm nhập đang vô tư đốt vài bộ hài cốt. Mọi chuyện kết thúc trước khi hắn kịp nhận ra kẻ tấn công.',
    'A large celestial platoon is marching to the north. The team hides behind a nearby rock, waiting for them to pass.': 'Một trung đội Thiên Giới lớn đang hành quân về phía bắc. Cả đội ẩn sau tảng đá gần đó và chờ chúng đi qua.',
    'A wounded Banshee digs a hole in the ground at surprising speed and disappears inside it.': 'Một Banshee bị thương đào hố với tốc độ đáng kinh ngạc rồi biến mất vào lòng đất.',
    "A flying ship is scanning the ground for living targets. You hope it didn't locate the expedition.": 'Một phi thuyền đang quét mặt đất để tìm mục tiêu sống. Chỉ mong nó chưa phát hiện đoàn thám hiểm.',
    'A huge golden ship, clearly not from this world, appears in the sky out of thin air. Tens of celestials jump down several meters on an unsuspecting Banshee.': 'Một phi thuyền vàng khổng lồ rõ ràng không thuộc thế giới này bỗng hiện ra giữa trời. Hàng chục chiến binh Thiên Giới nhảy từ độ cao vài mét xuống một Banshee không hề đề phòng.',
    'On your left, a group of celestials are pouring an unknown liquid inside one of the holes on the ground.': 'Bên trái, một nhóm chiến binh Thiên Giới đang đổ chất lỏng lạ vào một trong những hố trên mặt đất.',
    'The team proceeds with caution, surrounded by the sounds of the ongoing battle.': 'Cả đội thận trọng tiến bước giữa âm thanh của trận chiến vẫn đang diễn ra.',
    'On the ground are still visible the remains of a recent skirmish.': 'Tàn tích của một cuộc giao tranh vừa xảy ra vẫn còn hiện rõ trên mặt đất.',
    'A large group of flying eyes floating above suddenly divides, each racing in a different direction.': 'Một đàn mắt bay lớn lơ lửng phía trên đột ngột tách ra, mỗi con lao về một hướng khác nhau.',
    'Fires are burning all around the team, making the air almost unbreathable.': 'Lửa cháy khắp quanh đội, khiến không khí gần như không thể hít thở.',
    'The team steps into an unavoidable fight.': 'Cả đội bước vào một trận chiến không thể tránh khỏi.',
    'In the open field, the team is spotted from far away.': 'Giữa đồng trống, cả đội bị phát hiện từ rất xa.',
    'Just in time, the adventurers turn around to find enemies charging at them.': 'Vừa kịp lúc, các mạo hiểm giả quay lại và thấy kẻ địch đang lao thẳng tới.',
    'After a strenuous run, the expedition realizes it must face the chasing threat.': 'Sau một hồi chạy kiệt sức, đoàn thám hiểm nhận ra họ buộc phải đối mặt với mối đe dọa đang truy đuổi.',
    'From behind a large fire burning in the plain, something attacks the expedition.': 'Từ sau đám lửa lớn cháy giữa đồng, thứ gì đó lao vào tấn công đoàn thám hiểm.',
    'In the ground, in an abandoned Banshee burrow, lies a poorly concealed alien weapon. The team is about to step on the tripwire.': 'Trong một hang Banshee bỏ hoang dưới lòng đất có một vũ khí ngoài hành tinh được che giấu sơ sài. Cả đội sắp giẫm lên dây bẫy.',
    'The massive doors of the City of Larox, an ancient underground civilization lost for millennia, loom before the wary expedition. In the distance, a colossal artifact hums with seemingly random vibrations, reconfiguring itself in the blink of an eye. Using a sewer passage leading outside, the team slips past the marble walls undetected.': 'Những cánh cửa đồ sộ của Thành Larox, nền văn minh ngầm cổ đại đã thất lạc suốt hàng thiên niên kỷ, sừng sững trước đoàn thám hiểm cảnh giác. Ở phía xa, một cổ vật khổng lồ rung ngân theo nhịp tưởng như ngẫu nhiên và tái cấu hình chỉ trong chớp mắt. Lợi dụng đường cống dẫn ra ngoài, cả đội lẻn qua những bức tường cẩm thạch mà không bị phát hiện.',
    'From a nearby house, its walls adorned with arcane symbols, faint whispers in an ancient language can be heard.': 'Từ ngôi nhà gần đó với tường phủ đầy ký hiệu bí thuật vọng ra tiếng thì thầm khe khẽ bằng một ngôn ngữ cổ.',
    'In the distance, the Nexus emits a strong shockwave, and reconfigures itself once more.': 'Ở phía xa, Nexus phát ra một làn sóng xung kích mạnh rồi lại tái cấu hình.',
    'A procession of robed individuals walks through a large street ahead. The team proceeds with extreme caution.': 'Một đoàn người khoác áo choàng đi qua đại lộ phía trước. Cả đội tiến bước với sự thận trọng cao độ.',
    'On a nearby doorstep, five candles around a burnt, red incision suggest some kind of ritual recently took place.': 'Trên bậc cửa gần đó, năm ngọn nến bao quanh một vết khắc đỏ cháy sém cho thấy một nghi lễ nào đó vừa diễn ra.',
    'A skeleton lies suspended below a second floor window. What kind of civilized society allows this?': 'Một bộ xương bị treo dưới cửa sổ tầng hai. Xã hội văn minh kiểu gì lại cho phép chuyện này?',
    'Several crystals emerging from the ground, a natural occurrence in these caverns, vibrate in the same frequency of the Nexus.': 'Vài tinh thể mọc tự nhiên từ nền hang đang rung cùng tần số với Nexus.',
    'Candles in a nearby house are immediately put off as the team approaches.': 'Những ngọn nến trong ngôi nhà gần đó lập tức tắt phụt khi cả đội tới gần.',
    'A loud shout echoes in the distance, swiftly followed by a lightning in the same spot.': 'Một tiếng hét lớn vọng lên phía xa, ngay sau đó là tia sét giáng xuống đúng vị trí ấy.',
    'High above, a small, misshapen flying creature with a reddish hue soars through the air, clutching a piece of furniture.': 'Trên cao, một sinh vật bay nhỏ bé dị dạng màu đỏ lướt qua không trung, ôm chặt một món đồ nội thất.',
    'Two tall empty armors, animated by a blue light, stand guard to a nearby street.': 'Hai bộ giáp rỗng cao lớn được ánh sáng xanh điều khiển đang canh gác con phố gần đó.',
    'A sharp, whistling sound approaches at lightning speed.': 'Một tiếng rít sắc nhọn đang lao tới nhanh như chớp.',
    "Turning a corner, menacing figures notice the team's presence, and suddenly attack.": 'Vừa rẽ qua góc phố, những bóng dáng đe dọa nhận ra cả đội và bất ngờ tấn công.',
    'Behind the team, enemies try a surprise attack.': 'Phía sau, kẻ địch đang tìm cách đánh úp cả đội.',
    'Quick, unintelligible words are uttered nearby just before the team is attacked': 'Những câu thần chú nhanh và không thể hiểu nổi vang lên gần đó ngay trước khi cả đội bị tấn công.',
    'A nearby wooden door is obliterated by an overwhelming power. From the dark room beyond, enemies surge toward the team.': 'Một cánh cửa gỗ gần đó bị sức mạnh áp đảo nghiền nát. Từ căn phòng tối phía sau, kẻ địch tràn về phía cả đội.',
    'In the distance, the Nexus shifts rapidly, forming shapes that defy human understanding. It emits a pulsating light before settling into a new, enigmatic configuration.': 'Ở phía xa, Nexus chuyển động chóng mặt và tạo ra những hình dạng vượt ngoài hiểu biết của con người. Nó phát ánh sáng theo nhịp trước khi ổn định trong một cấu hình bí ẩn mới.',
    'From the feet of one of the team members, light begins to reveal the radial symmetry of a magic seal. A fraction of second later, a defensive spell is triggered.': 'Ánh sáng dưới chân một thành viên bắt đầu để lộ cấu trúc đối xứng tỏa tròn của một ma ấn. Chỉ một phần giây sau, phép phòng vệ được kích hoạt.',
    'The air grows intensely dry. In the distance, the massive artifact begins to pulsate with increasing intensity. Along the sides of the street, obsidian walls spring up in an instant, shielding the civilian buildings.': 'Không khí trở nên khô khốc dữ dội. Ở phía xa, cổ vật khổng lồ bắt đầu đập nhịp ngày càng mạnh. Dọc hai bên phố, những bức tường hắc diện thạch tức thì trồi lên che chắn các tòa nhà dân sự.',
    "An old man pulls the team aside. He praises your actions on the surface and, unlike the haughty members of the council, expresses genuine hope that you succeed in reaching the lower caverns. He uncorks a vial with a dark liquid.\nAdventurers' HP are fully restored, harmful effects are cleansed.": 'Một ông lão kéo cả đội sang bên. Ông ca ngợi những việc họ đã làm trên mặt đất và, khác với các thành viên hội đồng kiêu ngạo, chân thành hy vọng họ sẽ tới được những hang động sâu hơn. Ông mở nút một lọ chất lỏng sẫm màu.\nHP của các mạo hiểm giả được hồi đầy và mọi hiệu ứng bất lợi được thanh tẩy.',
    'After days spent in the dark, twisted tunnels stretching below the Nexus, the expedition finally spots a faint light. Deep within the caverns lies a lush plain, dimly lit by the glow of an active volcano. The valley teems with vegetation and hints at a primitive civilization — small stone pyramids are scattered across the landscape.': 'Sau nhiều ngày trong những đường hầm tối tăm, ngoằn ngoèo bên dưới Nexus, đoàn thám hiểm cuối cùng nhìn thấy ánh sáng mờ. Sâu trong hang động là một đồng bằng xanh tốt được ánh núi lửa đang hoạt động soi lờ mờ. Thung lũng tràn ngập cây cối và dấu tích của một nền văn minh nguyên thủy — những kim tự tháp đá nhỏ nằm rải rác khắp nơi.',
    'The team opens its way through a thick patch of ferns.': 'Cả đội mở đường xuyên qua một vùng dương xỉ dày đặc.',
    'A stream of lava cuts the expedition path. They coast it for a while, looking for a way to cross it.': 'Một dòng dung nham cắt ngang đường đi. Đoàn thám hiểm men theo nó một lúc để tìm chỗ vượt qua.',
    'A small path made of cobblestone leads somewhere in the middle of the vegetation.': 'Một lối nhỏ lát đá cuội dẫn vào nơi nào đó giữa thảm thực vật.',
    'A tall pyramids made of giant stone blocks stands in the middle of a small valley. Rolling drum noises come from inside.': 'Một kim tự tháp cao làm từ những khối đá khổng lồ đứng giữa thung lũng nhỏ. Tiếng trống dồn dập vọng ra từ bên trong.',
    'An ear shattering roar comes from ahead. The team hides for a while.': 'Một tiếng gầm đinh tai nhức óc vọng tới từ phía trước. Cả đội ẩn mình một lúc.',
    'In the distance, a deep rumble is followed swiftly by a small jet of lava erupting from the volcano.': 'Ở phía xa, sau tiếng ù trầm là một cột dung nham nhỏ phụt lên từ núi lửa.',
    'Above your heads, a swarm of the biggest birds you have ever seen crosses the sky.': 'Trên đầu, một đàn chim khổng lồ nhất mà cả đội từng thấy bay ngang bầu trời.',
    'A small, abandoned encampment lies in the middle of the forest. Below a steel cauldron, the embers are still smoking.': 'Một doanh trại nhỏ bị bỏ hoang nằm giữa rừng. Than hồng dưới chiếc vạc thép vẫn còn bốc khói.',
    'The team sees two tree stumps, and a sharp stone axe planted firmly in one of them.': 'Cả đội thấy hai gốc cây và một chiếc rìu đá sắc bén cắm chắc vào một gốc.',
    'A rhythmic, tribal song is being chanted in the distance. No one can recognize the language.': 'Một khúc hát bộ lạc theo nhịp đang vang lên ở phía xa. Không ai nhận ra thứ ngôn ngữ ấy.',
    'From beyond the thick wall of leaves, enemies charge at the team.': 'Từ sau bức tường lá dày, kẻ địch lao thẳng vào cả đội.',
    'Behind the team, enemies are quickly approaching.': 'Phía sau, kẻ địch đang nhanh chóng áp sát.',
    'A group of enemies emerges from the dark entrance of a nearby pyramid.': 'Một nhóm kẻ địch xuất hiện từ lối vào tối om của kim tự tháp gần đó.',
    'The team is ambushed by enemies, who were waiting on the tall trees.': 'Cả đội bị kẻ địch phục sẵn trên những cây cao đánh úp.',
    'As they round a bend in the winding stone path, the team is confronted by a group of enemies.': 'Khi vòng qua khúc cua trên con đường đá uốn lượn, cả đội đối mặt với một nhóm kẻ địch.',
    'An immense being, as tall as the ceiling of the cavern, emerges from the raging volcano.': 'Một sinh vật khổng lồ cao chạm trần hang bước ra từ ngọn núi lửa cuồng nộ.',
    'A brief shimmer on a nearby rock, unassuming at first glance, catches the attention of one of the adventurers. Once broken, the rock reveals the most beautiful gem they have ever seen.': 'Ánh lóe thoáng qua trên một tảng đá gần đó tưởng như bình thường thu hút sự chú ý của một mạo hiểm giả. Khi đập vỡ, tảng đá để lộ viên ngọc đẹp nhất họ từng thấy.',
    "In front of the expedition lies the endless Sha'huri Desert, inhabited by the once friendly people of the same name. Engaged in a thousand years battle with the Golden City, since the corruption took over, the war has ended and all contacts have been interrupted.": 'Trước mắt đoàn thám hiểm là Sa Mạc Sha\'huri vô tận, nơi cư ngụ của tộc người từng rất thân thiện mang cùng tên. Họ đã giao chiến với Thành Phố Hoàng Kim suốt một nghìn năm; kể từ khi sự tha hóa lan tới, chiến tranh chấm dứt và mọi liên lạc đều bị cắt đứt.',
    'A shadow in the barren wastelands quickly raises the group attention.': 'Một bóng đen giữa vùng hoang mạc lập tức thu hút sự chú ý của cả đội.',
    'The group is not alone. Few steps ahead, an enemy threat is ready to fight.': 'Cả đội không hề đơn độc. Chỉ vài bước phía trước, kẻ địch đã sẵn sàng giao chiến.',
    'Unusual vibrations below your feet precede the fight that is going to take place.': 'Những rung động bất thường dưới chân báo hiệu một trận chiến sắp xảy ra.',
    'Concealed by a dune, enemies were waiting for your arrival.': 'Ẩn sau một đụn cát, kẻ địch đã chờ sẵn đoàn thám hiểm.',
    'Screams pierce the stillness of the air, as the team is assaulted from ahead.': 'Tiếng thét xé tan bầu không khí tĩnh lặng khi cả đội bị tấn công từ phía trước.',
    "The sand drags below the adventurer's steps, in a landscape that hasn't changed for hours.": 'Cát níu lấy từng bước chân trong khung cảnh đã không thay đổi suốt nhiều giờ.',
    'A small trail of footprints lies on the ground. It must be recent.': 'Một vệt dấu chân nhỏ hiện trên mặt đất. Chúng có vẻ còn rất mới.',
    'With the sun so high in the sky, every step is harder than the previous.': 'Mặt trời đứng bóng khiến mỗi bước đi lại nặng nề hơn bước trước.',
    "The adventurers keep going forward, with only the occasional cactus breaking the landscape's monotony.": 'Các mạo hiểm giả tiếp tục tiến lên, chỉ đôi lúc có một cây xương rồng phá vỡ cảnh vật đơn điệu.',
    'Scorching winds caress the dunes ahead as the sand seems to dance atop of them.': 'Gió nóng rát lướt qua những đụn cát phía trước, khiến lớp cát trên đỉnh như đang nhảy múa.',
    'The dunes start moving like a tempestuous sea, animated by an ancient defense system. Sand figures start rising around you. They stretch as far as the eye can see…': 'Những đụn cát chuyển động như biển động dưới sức mạnh của một hệ thống phòng thủ cổ xưa. Các hình nhân bằng cát trỗi dậy khắp xung quanh, kéo dài đến tận chân trời…',
    'The team bravely advances between the overwhelming horde.': 'Cả đội dũng cảm tiến bước giữa đạo quân áp đảo.',
    "The ancient Sha'huri army attacks you with all its might.": 'Đội quân Sha\'huri cổ đại dốc toàn lực tấn công.',
    'As suddenly as it rose, the endless army crumbles to dust, unrecognizable from the sand below your feet.': 'Cũng đột ngột như lúc trỗi dậy, đạo quân vô tận tan thành bụi, không còn phân biệt được với lớp cát dưới chân.',
    'The sky darkens suddenly, and a brief but powerful sandstorm overwhelms the adventurers team.': 'Bầu trời đột ngột tối sầm và một cơn bão cát ngắn nhưng dữ dội nhấn chìm cả đội.',
    'Not much further, the team finds a rare desert oasis, full of palm trees and with a small pond of crystal clear water. They decide to rest for a while. Everyone recovered 10 HP and 10 Mana.': 'Không xa phía trước, cả đội tìm thấy một ốc đảo hiếm hoi với hàng cọ và hồ nước trong vắt. Mọi người nghỉ lại một lúc và hồi 10 HP cùng 10 Mana.',
    "Looking around, you didn't find anything of value.": 'Tìm kiếm xung quanh nhưng không phát hiện thứ gì có giá trị.',
    "The party sets foot in the forest just outside the guild's camp. Once a magical place where kids used to play, you feel the corruption tendrils are starting to reach these trees.": 'Cả đội đặt chân vào khu rừng ngay ngoài trại bang hội. Nơi đây từng là vùng đất nhiệm màu để trẻ nhỏ vui chơi, nhưng những xúc tu tha hóa dường như đã bắt đầu vươn tới các thân cây.',
    'There is a sound of a branch cracking. The team turns around.': 'Tiếng cành cây gãy vang lên. Cả đội lập tức quay lại.',
    'Few meters ahead, from the bushes, a pair of eyes are watching the expedition.': 'Cách đó vài mét, một đôi mắt đang dõi theo đoàn thám hiểm từ trong bụi rậm.',
    'Something was here before you, and has no intention to leave.': 'Có thứ gì đó đã ở đây từ trước và hoàn toàn không định rời đi.',
    'A low pitched growl echoes in the air.': 'Một tiếng gầm trầm thấp vang vọng trong không khí.',
    'You notice a movement behind the trees.': 'Bạn nhận thấy có chuyển động phía sau những thân cây.',
    'The team makes its way into a forest clearing, bathed in dim sunlight and surrounded by ancient trees.': 'Cả đội tiến vào một khoảng rừng trống ngập ánh nắng mờ, bao quanh bởi những cây cổ thụ.',
    'There is a narrow forest path ahead, enclosed by towering trees.': 'Phía trước là một lối mòn hẹp bị vây kín bởi những thân cây cao vút.',
    "This area is engulfed by an abundance of high trees and untamed wilderness. It's very hard to see the sky above.": 'Khu vực này bị phủ kín bởi cây cao và thiên nhiên hoang dã, gần như không thể nhìn thấy bầu trời.',
    'Blooming wildflowers are scattered everywhere, along with a few trees. Would have been a nice place for a camping trip in better times.': 'Hoa dại nở rộ khắp nơi xen giữa vài thân cây. Vào thời bình, đây hẳn là một nơi cắm trại tuyệt đẹp.',
    'The trees make space for a narrow forest path, now muddy and overgrown with shrubs.': 'Những thân cây nhường chỗ cho một lối mòn hẹp, giờ đã lầy lội và um tùm bụi rậm.',
    "A piercing scream echoes through the trees. It's rapidly getting closer…": 'Một tiếng thét chói tai vang vọng qua các tán cây và đang nhanh chóng tiến lại gần…',
    'Among the sparse trees, an enraged spirit stands before you. "Why did you do it…" — the wind whispers.': 'Giữa những thân cây thưa, một linh hồn phẫn nộ chắn trước mặt. “Tại sao các ngươi lại làm vậy…” — gió khẽ thì thầm.',
    "The group approaches an old fountain, covered in moss but otherwise perfectly functioning. After drinking its water, all wounds instantly disappear. Adventurers' HP are fully restored.": 'Cả đội đến gần một đài phun nước cổ phủ đầy rêu nhưng vẫn hoạt động hoàn hảo. Sau khi uống nước, mọi vết thương lập tức biến mất. HP của tất cả mạo hiểm giả được hồi đầy.',
    "The team finds a small fairy, trapped in a hunter's net and screaming at the top of her lungs. When they free her, she performs a quick spell and disappears into the crowns of the trees. Adventurers' Mana has been filled.": 'Cả đội tìm thấy một nàng tiên nhỏ mắc trong lưới thợ săn. Khi được giải thoát, cô niệm một phép ngắn rồi biến mất giữa tán cây. Mana của tất cả mạo hiểm giả được hồi đầy.',
    'A large pitfall setup by hunters, concealed by a patch of leaves, lies in front of the team.': 'Một hố bẫy lớn do thợ săn dựng lên, được che kín bằng lá, nằm ngay phía trước cả đội.',
    'Dodge roll is made with Dexterity. Difficulty is 10.': 'Kiểm tra né tránh bằng Nhanh nhẹn. Độ khó là 10.',
    "The smell of the burning graves permeates the air, raising a thick smoke curtain that is hard to penetrate. The team advances carefully through the edge of the thousand years battlefield, unable to imagine how the corruption could have twisted the Sha'huri and Imperial remains that were left behind.": 'Mùi mộ phần cháy khét tràn ngập không khí, tạo thành màn khói dày khó xuyên thấu. Cả đội thận trọng tiến dọc rìa chiến trường nghìn năm, không dám tưởng tượng sự tha hóa đã biến đổi hài cốt Sha\'huri và Đế Quốc đến mức nào.',
    "Dead hands grasp the ground below the team's feet, struggling to reach the surface.": 'Những bàn tay chết chóc cào cấu mặt đất dưới chân cả đội, cố vùng lên khỏi lòng đất.',
    'Right in front of you, something notices your presence. It instantly attacks.': 'Ngay phía trước, một thứ gì đó nhận ra sự hiện diện của cả đội và lập tức tấn công.',
    'Surprised by an unbearable stench, the team turns around to discover the enemies following them.': 'Bị giật mình bởi mùi hôi thối không thể chịu nổi, cả đội quay lại và phát hiện kẻ địch đang bám theo.',
    'Something stands up from the burning pile of bodies, refusing to stay dead.': 'Một thứ gì đó đứng dậy từ đống xác đang cháy, nhất quyết không chịu nằm yên.',
    'Without notice, the wind briefly opens up the smoke barrier, revealing the group to a hostile presence.': 'Không báo trước, gió thoáng mở màn khói và để lộ cả đội trước một hiện diện thù địch.',
    'The adventurers cover their mouths as they pass a pile of burning remains.': 'Các mạo hiểm giả che miệng khi đi ngang qua một đống hài cốt đang cháy.',
    'The team enters a frugal encampment, now deserted, with plates still full of food near an extinguished campfire.': 'Cả đội bước vào một doanh trại sơ sài đã bị bỏ hoang, những đĩa thức ăn vẫn còn nguyên bên đống lửa đã tắt.',
    'The sun, high in the sky, is barely visible though the tick fog.': 'Mặt trời dù đang ở rất cao vẫn gần như không thể nhìn thấy qua màn sương dày.',
    "The ground is scattered by Sha'huri remains, displaying the kind of wounds that no weapon made by men could inflict.": 'Mặt đất rải rác hài cốt Sha\'huri với những vết thương không vũ khí nào của con người có thể gây ra.',
    'In the distance, an army of undead is marching in casual directions.': 'Phía xa, một đạo quân xác sống đang bước đi vô định.',
    "A Will o' Wisp descends from the sky. Unlike the others, he doesn't seem hostile. It offers an Orb of Ectoplasm as a gift and departs without a word.": 'Một ma trơi hạ xuống từ bầu trời. Không giống đồng loại, nó không tỏ vẻ thù địch, trao tặng một Quả cầu ngoại chất rồi lặng lẽ rời đi.',
    "A cable holding an Imperial's explosive trap is stepped on.": 'Ai đó đã giẫm phải sợi dây kích hoạt bẫy nổ của Đế Quốc.',
    "The team finds themselves on a hidden Sha'huri seal, covered by the ashes. It lightens up, and horrible visions flood the adventurers minds.": 'Cả đội đứng trên một ấn Sha\'huri bị tro bụi che kín. Nó bừng sáng và những ảo ảnh kinh hoàng tràn vào tâm trí các mạo hiểm giả.',
    "The party crosses the unhinged gates of the empire's capital, setting foot on its marble streets. Once a home for merchants, artisans and intellectuals, the inhabitants have since descended into a feral state. The main body of the army was sent north in a rushed attempt to fight the source of the corruption, leaving here only a few guards and an elite force, albeit stripped to the bone, to protect the Emperor.": 'Cả đội bước qua cánh cổng long bản lề của kinh đô Đế quốc và đặt chân lên những con đường lát cẩm thạch. Nơi từng là mái nhà của thương nhân, nghệ nhân và học giả nay chỉ còn những cư dân đã hóa dại. Phần lớn quân đội bị vội vã điều lên phía bắc để chống lại nguồn tha hóa, chỉ để lại vài vệ binh cùng một lực lượng tinh nhuệ kiệt quệ bảo vệ Hoàng đế.',
    'After turning a corner, angry citizen attack the group.': 'Vừa rẽ qua một góc phố, những cư dân giận dữ lao vào tấn công cả đội.',
    'From behind a granite statue, an armed group comes forward.': 'Từ phía sau một pho tượng đá hoa cương, một nhóm có vũ trang bước ra.',
    'In front of the team, a mob with bloodshot eyes unsheathes its weapons.': 'Trước mặt cả đội, một đám đông mắt đỏ ngầu đồng loạt rút vũ khí.',
    'A calm, albeit incomprehensible discourse turn into screams of blind rage as the team approaches its source.': 'Một cuộc trò chuyện bình thản nhưng không thể hiểu nổi biến thành tiếng gào thét cuồng nộ khi cả đội tiến đến gần.',
    'The adventurers turn around, alerted by steps rushing from behind.': 'Các mạo hiểm giả quay phắt lại khi nghe tiếng chân gấp gáp lao tới từ phía sau.',
    'As the team is walking the marble streets, you hear a cracking sound from inside one of the houses. You enter to investigate.': 'Khi cả đội đi dọc những con phố cẩm thạch, tiếng rạn vỡ vang lên từ một ngôi nhà. Mọi người tiến vào điều tra.',
    'Under the gaze of the monstrous eye in the sky, the explorers struggle to maintain their resolve.': 'Dưới ánh nhìn của con mắt quái dị trên bầu trời, đoàn thám hiểm phải gắng sức giữ vững ý chí.',
    'The adventurers keep walking the city streets, among golden statues with intricate designs.': 'Các mạo hiểm giả tiếp tục băng qua phố thị giữa những pho tượng vàng được chạm trổ tinh xảo.',
    'The screams permeating the air seem to be getting closer, as you advance through the marble streets stained with blood.': 'Những tiếng thét phủ kín không gian dường như ngày một gần hơn khi cả đội tiến qua các con phố cẩm thạch nhuốm máu.',
    'A disoriented citizen passes close to the group, his face deformed by madness, yelling incomprehensible questions to the watcher above.': 'Một cư dân mất phương hướng đi sát qua cả đội, gương mặt méo mó vì điên loạn, gào lên những câu hỏi vô nghĩa với kẻ đang dõi nhìn từ trên cao.',
    'Suddenly a dull, static rumble fills the air. You can feel the endless anger of the being above, as its eye widens and the inhabitants enter a delirious state.\nEnemy damage is doubled for the duration.': 'Đột nhiên, một tiếng ù trầm đục và dai dẳng tràn ngập không khí. Có thể cảm nhận cơn giận vô tận của thực thể phía trên khi con mắt mở rộng và cư dân rơi vào trạng thái cuồng loạn.\nSát thương của kẻ địch được nhân đôi trong thời gian này.',
    'Finally the rumble stops. You can see a group of citizen nearby collapsing to the ground, exhausted.': 'Cuối cùng tiếng ù cũng dừng lại. Một nhóm cư dân gần đó kiệt sức và đổ gục xuống đất.',
    "You hear calls for help from a nearby basement. An old priest, who managed to hide before the fall of the city, asks you for some food. After fulfilling his request, he performs a healing spell to restore the team's energies.\nAdventurers' HP are fully restored.": 'Tiếng kêu cứu vọng lên từ một tầng hầm gần đó. Một tu sĩ già đã kịp ẩn náu trước khi thành phố sụp đổ xin cả đội chút thức ăn. Sau khi được giúp đỡ, ông thi triển phép chữa lành để hồi phục sức lực cho mọi người.\nHP của tất cả mạo hiểm giả được hồi đầy.',
    'The eye focuses on the Adventurers, drawing energy from them. This damage is magic, and reduced by Constitution.': 'Con mắt tập trung vào các mạo hiểm giả và rút lấy sinh lực của họ. Đây là sát thương phép và được giảm bởi Thể chất.',
    'As a team member opens a door nearby, an iron wedge swings towards the group.': 'Khi một thành viên mở cánh cửa gần đó, một nêm sắt bất ngờ vung thẳng về phía cả đội.',
    'Few people who enter Blackwater Port uninvited get to leave on their feet. Controlled by the fearsome pirates of the nearby Skull Island, because of their agreements with the Empire this was the central commercial hub of the region. It is said that the place was already cursed before the corruption struck.': 'Rất ít kẻ tự tiện bước vào Cảng Hắc Thủy có thể rời đi bằng chính đôi chân mình. Bị kiểm soát bởi những hải tặc đáng sợ trên Đảo Đầu Lâu gần đó, nơi đây từng là trung tâm thương mại của cả vùng nhờ thỏa thuận của chúng với Đế quốc. Người ta nói vùng đất này đã bị nguyền rủa từ trước khi sự tha hóa ập đến.',
    'Hostile entities appear from behind a nearby lowered sail': 'Những thực thể thù địch xuất hiện sau cánh buồm đang hạ gần đó',
    'A glass bottle cracks nearby. Immediately after, something attack you.': 'Một chai thủy tinh vỡ gần đó. Ngay sau đó, thứ gì đó lao vào tấn công cả đội.',
    'Distracted by the rustling of the waves, you realize almost too late you are being followed.': 'Mải chú ý tiếng sóng rì rào, cả đội gần như nhận ra quá muộn rằng mình đang bị bám theo.',
    'From below the docks, something emerges. It wants your heads.': 'Một thứ gì đó trồi lên từ dưới cầu cảng. Nó muốn lấy đầu của cả đội.',
    'The cracking of the wood planks below alerts you of the incoming attack.': 'Tiếng ván gỗ rạn nứt bên dưới cảnh báo cả đội về một cuộc tấn công sắp tới.',
    'Walking along the quay, the several docked ships are all in ruins. You swear you saw a candle light in a distant cabin.': 'Dọc theo bến cảng, mọi con tàu đang neo đều đã mục nát. Bạn thề rằng vừa thấy ánh nến trong một khoang tàu xa xa.',
    'A building near the coast crumbled on the paved street. The team is forced to board one of the decaying ship to circumvent the obstacle.': 'Một tòa nhà ven biển đã sụp xuống con đường lát đá. Cả đội buộc phải lên một con tàu mục nát để vòng qua chướng ngại.',
    "The wood below the team's feet creaks dangerously as they advance through the docks.": 'Ván gỗ dưới chân kêu cót két đầy nguy hiểm khi cả đội tiến qua cầu cảng.',
    "A ship sailing far from your position sounds its horns. It's unlikely they saw the expedition… right?": 'Một con tàu ở rất xa kéo còi. Chắc chúng không thể nhìn thấy đoàn thám hiểm… phải không?',
    'A feral monkey rushes at the team, armed with a dull knife. Suddenly, a huge tentacle emerges from the dark sea and drags it below. This is a dangerous place…': 'Một con khỉ hoang cầm dao cùn lao về phía cả đội. Đột nhiên, một xúc tu khổng lồ trồi khỏi mặt biển đen và kéo nó xuống sâu. Đây thực sự là một nơi nguy hiểm…',
    "It's been a while since you haven't ran into a soul… what could be scaring these ruthless pirates?": 'Đã khá lâu không gặp một bóng người… thứ gì có thể khiến đám hải tặc tàn nhẫn này khiếp sợ?',
    'You notice a huge, dark spot just below the surface. What kind of horror lies under the sea?': 'Một bóng đen khổng lồ hiện ra ngay dưới mặt nước. Nỗi kinh hoàng nào đang ẩn mình dưới biển?',
    'The unknown mass goes back to the dark ocean depths.': 'Khối vật thể bí ẩn rút trở lại vực sâu tăm tối của đại dương.',
    "A small round object is floating in the water. With some difficulty, the team manages to retrieve an Eye of the Abyss. The monster is far from dead, but it's surely hurt.": 'Một vật tròn nhỏ đang nổi trên mặt nước. Sau nhiều khó khăn, cả đội vớt được một Con mắt Vực thẳm. Con quái vật còn lâu mới chết, nhưng chắc chắn đã bị thương.',
    'A scared capuchin monkey emerges from beyond some crates. How long was it hiding there? It hands you a polished oyster pearl, and runs to the woods outside the port.': 'Một con khỉ mũ sợ hãi bước ra từ sau những thùng hàng. Nó đã trốn ở đó bao lâu rồi? Nó trao cho cả đội một viên ngọc trai được đánh bóng rồi chạy về khu rừng ngoài cảng.',
    'A tripwire suddenly snaps, triggering nearby flintlock guns aimed at the team.': 'Một dây bẫy bất ngờ bật đứt, kích hoạt những khẩu súng hỏa mai gần đó đang chĩa vào cả đội.',
    'When a team member steps on a hidden pressure plate, a huge anchors falls from above.': 'Khi một thành viên giẫm lên bàn ép ẩn, một chiếc neo khổng lồ rơi xuống từ trên cao.',
    'A pile of gold is sitting in front of the adventurers. As soon as they touch it, the curse activates and it turns into a sticky, corrosive substance.': 'Một đống vàng nằm trước mặt các mạo hiểm giả. Ngay khi họ chạm vào, lời nguyền kích hoạt và biến nó thành một chất dính có tính ăn mòn.',
    'A suspended net is released onto the adventurers, ensnaring them. The water in the chamber starts rising.': 'Một tấm lưới treo được thả xuống, trói chặt các mạo hiểm giả. Nước trong căn phòng bắt đầu dâng lên.',
    "The team begins the climb of the mountain range known as the Frostbite Peaks, well aware that it's freezing temperature and steep mountain passes are not the greatest danger: these mountains are said to be inhabited by trolls, a primitive humanoid species gifted with inhuman physical capabilities.": 'Cả đội bắt đầu leo lên dãy núi được gọi là Đỉnh Băng Giá, hiểu rõ rằng nhiệt độ đóng băng và những con đèo dựng đứng chưa phải hiểm họa lớn nhất: tương truyền nơi đây là lãnh địa của Troll, một giống người nguyên thủy sở hữu sức mạnh thể chất phi nhân.',
    'The team notices a pungent smell in the air. Not long after, it discovers why.': 'Cả đội nhận thấy một mùi hăng nồng trong không khí. Chẳng bao lâu sau, họ hiểu được nguyên nhân.',
    'There are footsteps in the snow. The trail ends soon to a group of enemies.': 'Có những dấu chân trên tuyết. Vệt dấu nhanh chóng dẫn tới một nhóm kẻ địch.',
    'Behind a nearby rock, enemies were waiting for you.': 'Kẻ địch đã chờ sẵn phía sau một tảng đá gần đó.',
    'Something was perfectly camouflaged in the white snow. It attacks the expedition as soon as they approach.': 'Một thứ gì đó ngụy trang hoàn hảo trong nền tuyết trắng và tấn công ngay khi đoàn thám hiểm đến gần.',
    'From a nearby cave opening, a group of enemies emerges to attack the team.': 'Một nhóm kẻ địch tràn ra từ cửa hang gần đó và tấn công cả đội.',
    'A narrow passage forces the expedition to form a line and hug the mountain, being extremely careful as to not fall in the chasm below.': 'Lối đi hẹp buộc đoàn thám hiểm xếp thành một hàng, bám sát vách núi và hết sức cẩn thận để không rơi xuống vực sâu.',
    'Even with the heaviest equipment, the ice cold climate makes every step harder than the previous.': 'Dù mặc trang bị dày nhất, khí hậu lạnh buốt vẫn khiến mỗi bước chân nặng nề hơn bước trước.',
    'The expedition stops for a break and lights a fire in a shallow caves opening.': 'Đoàn thám hiểm dừng nghỉ và nhóm lửa trong cửa một hang nông.',
    'In the distance, a magic pillar going all the way to the sky is visible. You must severe the link as soon as possible.': 'Ở phía xa hiện ra một cột ma lực vươn thẳng tới trời cao. Mối liên kết ấy phải được cắt đứt càng sớm càng tốt.',
    'The team discovers a frozen pile of bodies, perfectly preserved from the cold. Bite marks and sings of blunt force trauma indicate that cold was unlikely the cause of death.': 'Cả đội phát hiện một đống thi thể đông cứng được cái lạnh bảo quản nguyên vẹn. Dấu cắn và vết chấn thương do vật cùn cho thấy họ khó có thể chết vì rét.',
    "Climbing gear is left suspended on the mountain side, covering it almost entirely. It has to be from the imperial army's passage.": 'Dụng cụ leo núi bị bỏ lại treo kín gần như cả sườn núi. Chúng hẳn thuộc về đoàn quân Đế quốc từng đi qua.',
    'There is imperial equipment scattered all over an extinguished campfire. It must be recent.': 'Trang bị Đế quốc nằm rải rác quanh một đống lửa đã tắt. Dấu vết có vẻ còn rất mới.',
    'The wind gets suddenly colder. A blizzard descends upon the mountains, greatly reducing visibility and increasing the threat of freezing.': 'Gió đột ngột trở nên lạnh buốt. Một trận bão tuyết tràn xuống núi, làm giảm nghiêm trọng tầm nhìn và tăng nguy cơ đóng băng.',
    'The blizzard has ceased.': 'Trận bão tuyết đã ngừng.',
    'A pressure plate, hidden by snow, makes the ice crack below the teams feet. Soon enough, everyone will be submerged in freezing water.': 'Một bàn ép ẩn dưới tuyết làm lớp băng dưới chân cả đội nứt vỡ. Chẳng bao lâu nữa mọi người sẽ chìm trong làn nước giá buốt.',
    "Abandoned for centuries, these mines were the main source of the Empire for precious obsidian. Now, they are inhabited by all kinds of creatures that dwell in the dark. Legends say an unspeakable horror has inhabited the mines' lowest levels, and when an unnatural darkness arises any explorer should run for their lives.": 'Bị bỏ hoang suốt nhiều thế kỷ, những hầm mỏ này từng là nguồn hắc diện thạch quý giá chủ yếu của Đế quốc. Giờ đây đủ loại sinh vật ưa bóng tối trú ngụ bên trong. Truyền thuyết kể rằng một nỗi kinh hoàng không thể gọi tên sống ở tầng sâu nhất; khi bóng tối phi tự nhiên trỗi dậy, mọi nhà thám hiểm nên chạy để giữ mạng.',
    'Not far from your position, eerie steps on the rocky pavement alert the team.': 'Không xa vị trí của cả đội, tiếng bước chân rợn người trên nền đá vang lên cảnh báo.',
    'The limestone pillars concealed hostile presences.': 'Những cột đá vôi che giấu các hiện diện thù địch.',
    'After turning a corner, something notices your presence and attacks you.': 'Vừa rẽ qua một góc, thứ gì đó nhận ra sự hiện diện của cả đội và lao vào tấn công.',
    'Hidden in a dark spot, monsters leap at the expedition.': 'Ẩn mình trong một góc tối, lũ quái vật bất ngờ nhảy xổ vào đoàn thám hiểm.',
    'From a dark pit in the ground, leading to the infested mine depths, monsters are crawling towards the team.': 'Từ một hố tối dẫn xuống tầng mỏ bị xâm chiếm, lũ quái vật bò dần về phía cả đội.',
    'Extinguished torches line up the walls of a corridor, way too damp to be ignited again.': 'Những ngọn đuốc đã tắt xếp dọc tường hành lang, ẩm đến mức không thể thắp lại.',
    'An empty abandoned cart lies on rails now full of rust.': 'Một xe goòng trống bị bỏ lại trên đường ray đã phủ đầy gỉ sét.',
    'Thousand years old stalagmites descend from the rock ceiling, trickling drops of water in a small puddle.': 'Những thạch nhũ nghìn năm rủ xuống từ trần đá, để từng giọt nước rơi vào một vũng nhỏ.',
    "You hear flowing water near you: a small river must have found its way in the mine's crevasses.": 'Tiếng nước chảy vang lên gần đó; một dòng sông nhỏ hẳn đã len qua các khe nứt của hầm mỏ.',
    'The team coasts a precipice leading into the void. Below, tens of skeletons still clad in imperial armors lie suspended into a huge spiderweb.': 'Cả đội men theo một vực thẳm dẫn vào hư vô. Phía dưới, hàng chục bộ xương vẫn mặc giáp Đế quốc bị treo trong một mạng nhện khổng lồ.',
    'Mining tools lie abandoned on the ground. An old mining expedition must have met something they were unprepared for.': 'Dụng cụ khai mỏ bị bỏ lại trên mặt đất. Một đoàn thợ mỏ trước đây hẳn đã chạm trán thứ gì đó ngoài dự liệu.',
    'Imperial soldiers corpses are all over the place. These caverns are dangerous enough to pose a significant threat even to the best equipped army of the known world.': 'Thi thể binh lính Đế quốc nằm khắp nơi. Những hang động này nguy hiểm đến mức đe dọa cả đạo quân được trang bị tốt nhất thế giới.',
    'An unspeakable horror noticed your presence.': 'Một nỗi kinh hoàng không thể gọi tên đã nhận ra sự hiện diện của cả đội.',
  }
  if (staticLogs[line]) return staticLogs[line]
  match = line.match(/^(.+) lost (\d+) HP from the fall\.$/)
  if (match) return `${localizeName(language, match[1])} mất ${match[2]} HP do cú rơi.`
  match = line.match(/^(.+) used Botched Sacrifice, but no one answers the call\.$/)
  if (match) return `${localizeName(language, match[1])} dùng Hiến tế thất bại, nhưng không ai đáp lại lời triệu gọi.`
  match = line.match(/^Sha'huri deterrent system activated, threat level: \[(\d+)\/100\]$/)
  if (match) return `Hệ thống răn đe Sha'huri đã kích hoạt, mức đe dọa: [${match[1]}/100]`
  match = line.match(/^A rumbling sound is quickly approaching\. With an average dexterity of (\d+), it will reach the team in (\d+) turns\.$/)
  if (match) return `Tiếng ầm ầm đang nhanh chóng tiến lại gần. Với Nhanh nhẹn trung bình ${match[1]}, nó sẽ đuổi kịp cả đội sau ${match[2]} lượt.`
  match = line.match(/^In the distance, the Nexus shifts rapidly, forming shapes that defy human understanding\. It emits a pulsating light before settling into a new, enigmatic configuration\.\nMagic Damage amplification is now (-?\d+)%$/)
  if (match) return `Ở phía xa, Nexus chuyển động chóng mặt và tạo ra những hình dạng vượt ngoài hiểu biết của con người. Nó phát ánh sáng theo nhịp trước khi ổn định trong một cấu hình bí ẩn mới.\nKhuếch đại sát thương phép hiện là ${match[1]}%.`
  match = line.match(/^The Fire Ritual is (\d+)% complete\.$/)
  if (match) return `Nghi lễ Lửa đã hoàn thành ${match[1]}%.`
  match = line.match(/^Looking around the place, you found (\d+) (.+)\.$/)
  if (match) return `Tìm kiếm xung quanh, bạn tìm thấy ${match[1]} ${localizeName(language, match[2])}.`
  match = line.match(/^The Will o' Wisp thanks you for freeing it from its mortal body\. \[Will o' Wisps slain: (\d+)\/200\]$/)
  if (match) return `Ma trơi cảm ơn bạn đã giải thoát nó khỏi thể xác phàm trần. [Ma trơi đã tiêu diệt: ${match[1]}/200]`
  match = line.match(/^Dodge roll is made with (Dexterity|Constitution|Intelligence)\. Difficulty is (\d+)\.$/)
  if (match) {
    const stat = match[1] === 'Dexterity' ? 'Nhanh nhẹn' : match[1] === 'Constitution' ? 'Thể chất' : 'Trí tuệ'
    return `Kiểm tra né tránh bằng ${stat}. Độ khó là ${match[2]}.`
  }
  match = line.match(/^(\d+) HP was drawn from (.+)\.$/)
  if (match) return `${match[1]} HP đã bị rút khỏi ${localizeName(language, match[2])}.`
  match = line.match(/^Behind a nearby rock lies a winterwood crate with a huge iron lock\. It must be a Troll storage of sorts\. With a Dexterity of (\d+), (.+) tries to pick the lock\. It has a (\d+)% proability of success\.$/)
  if (match) return `Sau một tảng đá gần đó là chiếc rương gỗ đông với ổ khóa sắt khổng lồ, có lẽ là kho của Troll. Với ${match[1]} Nhanh nhẹn, ${localizeName(language, match[2])} thử phá khóa. Tỷ lệ thành công là ${match[3]}%.`
  match = line.match(/^(.+) failed, breaking the lock\.$/)
  if (match) return `${localizeName(language, match[1])} thất bại và làm hỏng ổ khóa.`
  match = line.match(/^(.+) succeeded!$/)
  if (match) return `${localizeName(language, match[1])} đã thành công!`
  match = line.match(/^(.+) couldn't avoid the trap and took (\d+) damage\. Dodge chance was (\d+)%\.$/)
  if (match) return `${localizeName(language, match[1])} không né được bẫy và chịu ${match[2]} sát thương. Tỷ lệ né là ${match[3]}%.`
  match = line.match(/^(.+) avoided the trap\. Dodge chance was (\d+)%$/)
  if (match) return `${localizeName(language, match[1])} đã né được bẫy. Tỷ lệ né là ${match[2]}%.`
  match = line.match(/^(.+) disarmed the trap\.$/)
  if (match) return `${localizeName(language, match[1])} đã vô hiệu hóa cái bẫy.`
  match = line.match(/^The party entered (.+)\.$/)
  if (match) return `Đội đã tiến vào ${localizeName(language, match[1])}.`
  match = line.match(/^Encountered (.+)\.$/)
  if (match) return `Chạm trán ${match[1].split(', ').map((name) => localizeName(language, name)).join(', ')}.`
  match = line.match(/^Found (\d+)[×Ã—] (.+)\.$/)
  if (match) return `Tìm thấy ${match[1]}× ${localizeName(language, match[2])}.`
  match = line.match(/^(.+) missed (.+)\.$/)
  if (match) return `${localizeName(language, match[1])} đánh hụt ${localizeName(language, match[2])}.`
  match = line.match(/^(.+) dealt (\d+)( critical)? damage to (.+)\.$/)
  if (match) return `${localizeName(language, match[1])} gây ${match[2]} sát thương${match[3] ? ' chí mạng' : ''} lên ${localizeName(language, match[4])}.`
  match = line.match(/^(.+) healed (.+) for (\d+)\.$/)
  if (match) return `${localizeName(language, match[1])} hồi ${match[3]} máu cho ${localizeName(language, match[2])}.`
  match = line.match(/^(.+) is stunned and cannot act\.$/)
  if (match) return `${localizeName(language, match[1])} bị choáng và không thể hành động.`
  match = line.match(/^(.+) is silenced\.$/)
  if (match) return `${localizeName(language, match[1])} bị câm lặng.`
  match = line.match(/^(.+) suffered (\d+) status damage\.$/)
  if (match) return `${localizeName(language, match[1])} chịu ${match[2]} sát thương trạng thái.`
  match = line.match(/^(.+) recovered (\d+) health\.$/)
  if (match) return `${localizeName(language, match[1])} hồi phục ${match[2]} máu.`
  match = line.match(/^(.+) escaped\.$/)
  if (match) return `${localizeName(language, match[1])} đã bỏ chạy.`
  match = line.match(/^(.+) blocked (.+)'s attack\.$/)
  if (match) return `${localizeName(language, match[1])} chặn đòn tấn công của ${localizeName(language, match[2])}.`
  match = line.match(/^(.+) returned to life\.$/)
  if (match) return `${localizeName(language, match[1])} đã hồi sinh.`
  match = line.match(/^(.+) retaliated for (\d+) damage against (.+)\.$/)
  if (match) return `${localizeName(language, match[1])} phản đòn gây ${match[2]} sát thương lên ${localizeName(language, match[3])}.`
  match = line.match(/^(.+) counterattacked (.+)\.$/)
  if (match) return `${localizeName(language, match[1])} phản công ${localizeName(language, match[2])}.`
  match = line.match(/^(.+) shielded (.+) for (\d+)\.$/)
  if (match) return `${localizeName(language, match[1])} tạo ${match[3]} khiên cho ${localizeName(language, match[2])}.`
  match = line.match(/^(.+) suffered a broken tether\.$/)
  if (match) return `Liên kết của ${localizeName(language, match[1])} đã bị phá vỡ.`
  match = line.match(/^(.+) returned with a feeble tether\.$/)
  if (match) return `${localizeName(language, match[1])} hồi sinh bằng một liên kết mong manh.`
  match = line.match(/^(.+) reanimated (.+) as (.+)\.$/)
  if (match) return `${localizeName(language, match[1])} hồi sinh ${localizeName(language, match[2])} thành ${localizeName(language, match[3])}.`
  match = line.match(/^(.+)'s final effects spread across the battlefield\.$/)
  if (match) return `Hiệu ứng cuối cùng của ${localizeName(language, match[1])} lan khắp chiến trường.`
  match = line.match(/^(.+) reached level (\d+)\.$/)
  if (match) return `${match[1]} đã đạt cấp ${match[2]}.`
  match = line.match(/^(.+) has been unlocked\.$/)
  if (match) return `Đã mở khóa ${localizeName(language, match[1])}.`
  return line
}

export function useI18n() {
  const language = useContext(I18nContext)
  return {
    language,
    t: (key: string, variables?: Record<string, string | number>) => translate(language, key, variables),
    name: (value: string) => localizeName(language, value),
    description: (id: string, fallback: string) => localizeDescription(language, id, fallback),
    status: (value: StatusEffectType) => localizeStatus(language, value),
    log: (value: string) => localizeLog(language, value),
  }
}
